window.DULIEU_CHUYENMUC_MASTER = {
    "XEMTUOI_BAI_VIET_CUSTOM":  "[{\"id\":\"post-xem-tuoi-vo-chong\",\"tieuDe\":\"Xem Tuổi Vợ Chồng Hòa Hợp: Luận Giải Cung Phi Bát Trạch \\u0026 Ngũ Hành Nạp Âm\",\"chuyenMuc\":\"Xem tuổi vợ chồng\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"15/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tuổi Vợ Chồng.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Tường giải các yếu tố cốt lõi khi xem tuổi vợ chồng: Ngũ Hành tương sinh, Cung Phi Bát Tự, Thiên Can Địa Chi hòa hợp để gia đạo êm ấm, phú quý bền lâu.\",\"noiDung\":\"\\u003ch3\\u003e1. Tầm quan trọng của việc xem tuổi vợ chồng\\u003c/h3\\u003e\\n      \\u003cp\\u003eHôn nhân là việc trọng đại cả đời người. Trong văn hóa cổ truyền Á Đông, việc xem tuổi vợ chồng không phải là mê tín mà là sự ứng dụng tinh hoa thuật số Bát Tự và Kinh Dịch để tìm kiếm sự hòa hợp âm dương giữa hai cá thể.\\u003c/p\\u003e\\n      \\n      \\n      \\u003ch3\\u003e2. 5 Yếu tố then chốt khi định tuổi phu thê\\u003c/h3\\u003e\\n      \\u003cul\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eNgũ hành bản mệnh:\\u003c/strong\\u003e Phân định mệnh nạp âm tương sinh hay tương khắc. Ví dụ Thủy sinh Mộc, Kim sinh Thủy là đại cát; Thủy khắc Hỏa, Mộc khắc Thổ cần có phương án hóa giải phong thủy hợp lý.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eCung Phi Bát Trạch:\\u003c/strong\\u003e Yếu tố quyết định chất lượng hôn nhân. Đẹp nhất là gặp các cung: Sinh Khí, Diên Niên, Thiên Y, Phục Vị. Tránh gặp Ngũ Quỷ, Tuyệt Mệnh, Họa Hại, Lục Sát.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eThiên Can:\\u003c/strong\\u003e Xét Can hợp (như Giáp - Kỷ, Ất - Canh, Bính - Tân) hay Can phá để biết sự tương trợ trong tư duy và định hướng cuộc sống.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eĐịa Chi:\\u003c/strong\\u003e Ưu tiên Tam Hợp (Thân - Tý - Thìn, Dần - Ngọ - Tuất...), Lục Hợp. Tránh Tứ Hành Xung và Lục Hại.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eThiên Mệnh năm sinh:\\u003c/strong\\u003e Đánh giá nền tảng phước đức và tương quan sinh khắc giữa hai gia đình.\\u003c/li\\u003e\\n      \\u003c/ul\\u003e\\n\\n      \\u003ch3\\u003e3. Cách hóa giải khi tuổi vợ chồng có xung khắc\\u003c/h3\\u003e\\n      \\u003cp\\u003eCổ nhân có câu: \\u003cem\\u003e\\\"Nhân định thắng thiên\\\"\\u003c/em\\u003e. Khi hai người có tình cảm sâu đậm nhưng cung mệnh xung khắc, hoàn toàn có thể hóa giải bằng:\\u003c/p\\u003e\\n      \\u003cp\\u003e• Chọn năm sinh con hợp tuổi cả cha lẫn mẹ để làm cầu nối hóa giải mâu thuẫn ngũ hành.\\u003c/p\\u003e\\n      \\u003cp\\u003e• Bố trí hướng phòng ngủ, hướng bếp, bàn thờ theo cung vị cát lành tương sinh cho người mang mệnh yếu hơn.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"post-xem-tuoi-sinh-con\",\"tieuDe\":\"Xem Tuổi Sinh Con Hợp Tuổi Cha Mẹ: Đón Tài Đón Lộc, Gia Đạo Hưng Long\",\"chuyenMuc\":\"Xem tuổi sinh con\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"15/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tuổi Sinh Con.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Bí quyết xem năm sinh con tương sinh bản mệnh bố mẹ, giúp kích hoạt vượng khí gia đình, con cái thông minh mạnh khỏe, công danh tấn tài.\",\"noiDung\":\"\\u003ch3\\u003e1. Ý nghĩa của việc chọn năm sinh con\\u003c/h3\\u003e\\n      \\u003cp\\u003eCon cái là lộc trời ban. Tuy nhiên, việc tính toán năm sinh con hợp bản mệnh của cha và mẹ sẽ tạo nên một thế cục ngũ hành tương sinh, giúp cuộc sống gia đình thêm phần thuận lợi, công danh của cha mẹ thăng tiến và đứa trẻ lớn lên trong môi trường hòa hợp.\\u003c/p\\u003e\\n      \\n\\n      \\u003ch3\\u003e2. Ba nguyên tắc vàng khi chọn năm sinh con\\u003c/h3\\u003e\\n      \\u003cul\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eNgũ hành nạp âm tương sinh:\\u003c/strong\\u003e Mệnh của con nên tương sinh cho mệnh của bố mẹ, hoặc mệnh bố mẹ tương sinh cho con. Tránh ngũ hành của con tương khắc mạnh với cả cha lẫn mẹ.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eThiên Can tương hợp:\\u003c/strong\\u003e Thiên can năm sinh của con không nên xung phá thiên can của bố mẹ (tránh Canh phá Giáp, Tân phá Ất, Nhâm phá Bính...).\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eĐịa Chi không phạm tứ hành xung:\\u003c/strong\\u003e Tránh các cặp địa chi tương xung trực tiếp như Tý - Ngọ, Mão - Dậu, Thìn - Tuất, Sửu - Mùi.\\u003c/li\\u003e\\n      \\u003c/ul\\u003e\\n\\n      \\u003ch3\\u003e3. Lời khuyên từ chuyên gia phong thủy\\u003c/h3\\u003e\\n      \\u003cp\\u003eDù sinh con năm nào, điều quan trọng nhất vẫn là sự yêu thương, chăm sóc và giáo dục con trẻ từ tâm đức của cha mẹ. Phong thủy là trợ lực, phước đức là gốc rễ bền vững nhất.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"post-xem-tuoi-ket-hon\",\"tieuDe\":\"Xem Tuổi Kết Hôn: Tránh Kim Lâu, Nghênh Đón Hỷ Thần Đại Cát\",\"chuyenMuc\":\"Xem tuổi kết hôn\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"14/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tuổi Kết Hôn.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Phương pháp tính tuổi Kim Lâu chính xác cho cô dâu, cách chọn năm lành tháng tốt để cử hành hôn lễ tròn vẹn viên mãn.\",\"noiDung\":\"\\u003ch3\\u003e1. Vì sao cưới hỏi cần xem tuổi cô dâu?\\u003c/h3\\u003e\\n      \\u003cp\\u003eTục ngữ có câu: \\u003cem\\u003e\\\"Lấy vợ xem tuổi đàn bà, làm nhà xem tuổi đàn ông\\\"\\u003c/em\\u003e. Khi định ngày cưới hỏi, việc xem tuổi cô dâu có phạm Kim Lâu hay không là ưu tiên số một nhằm đảm bảo sự bình an cho gia đạo.\\u003c/p\\u003e\\n      \\n\\n      \\u003ch3\\u003e2. Cách tính hạn Kim Lâu\\u003c/h3\\u003e\\n      \\u003cp\\u003eLấy tuổi mụ của nữ chia cho 9, nếu số dư rơi vào:\\u003c/p\\u003e\\n      \\u003cul\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eDư 1 (Kim Lâu Thân):\\u003c/strong\\u003e Hại cho chính bản thân người kết hôn.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eDư 3 (Kim Lâu Thê):\\u003c/strong\\u003e Gây bất lợi cho người phối ngẫu (chồng).\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eDư 6 (Kim Lâu Tử):\\u003c/strong\\u003e Bất lợi cho đường con cái.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eDư 8 (Kim Lâu Lục Súc):\\u003c/strong\\u003e Gây tổn hại kinh tế, chăn nuôi, tài sản gia đình.\\u003c/li\\u003e\\n      \\u003c/ul\\u003e\\n\\n      \\u003ch3\\u003e3. Cách thức hóa giải Kim Lâu khi muốn cưới gấp\\u003c/h3\\u003e\\n      \\u003cp\\u003eNếu gặp năm Kim Lâu nhưng không thể hoãn cưới, cổ nhân thường áp dụng phương pháp đón dâu hai lần hoặc cử hành hôn lễ sau ngày Đông Chí / sinh nhật cô dâu để hóa sát đón lành.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"post-xem-tuoi-hop-nhau\",\"tieuDe\":\"Xem Tuổi Hợp Nhau: Luận Nhị Hợp, Tam Hợp \\u0026 Bát Tự Đắc Cát Tường\",\"chuyenMuc\":\"Xem tuổi hợp nhau\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"14/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tuổi Hợp Nhau.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Tra cứu sự hòa hợp giữa các tuổi theo quy luật Nhị Hợp, Tam Hợp, Lục Xung, Lục Hại giúp bạn thấu hiểu mối quan hệ nhân duyên và đối tác.\",\"noiDung\":\"\\u003ch3\\u003e1. Sự tương tác giữa 12 Địa Chi\\u003c/h3\\u003e\\n      \\u003cp\\u003e12 con giáp tương ứng với 12 địa chi trong vũ trụ học phương Đông. Mỗi con giáp đều có những mối quan hệ tương hỗ hoặc khắc chế lẫn nhau:\\u003c/p\\u003e\\n      \\n      \\n      \\u003ch3\\u003e2. Bảng đối chiếu Tam Hợp \\u0026 Nhị Hợp\\u003c/h3\\u003e\\n      \\u003cul\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eTam Hợp Thủy cục:\\u003c/strong\\u003e Thân - Tý - Thìn (Thông tuệ, linh hoạt).\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eTam Hợp Hỏa cục:\\u003c/strong\\u003e Dần - Ngọ - Tuất (Nhiệt huyết, chính trực).\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eTam Hợp Kim cục:\\u003c/strong\\u003e Tỵ - Dậu - Sửu (Cương nghị, nguyên tắc).\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eTam Hợp Mộc cục:\\u003c/strong\\u003e Hợi - Mão - Mùi (Bao dung, thiện lương).\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eSáu cặp Nhị Hợp:\\u003c/strong\\u003e Tý - Sửu, Dần - Hợi, Mão - Tuất, Thìn - Dậu, Tỵ - Thân, Ngọ - Mùi.\\u003c/li\\u003e\\n      \\u003c/ul\\u003e\\n\\n      \\u003ch3\\u003e3. Ứng dụng trong cuộc sống\\u003c/h3\\u003e\\n      \\u003cp\\u003eXem tuổi hợp nhau giúp bạn tìm được người tri kỷ trong tình yêu, bạn bè tâm giao trong cuộc sống và đối tác tin cậy trên thương trường.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"post-xem-tuoi-lam-nha\",\"tieuDe\":\"Xem Tuổi Làm Nhà: Tra Cứu Tam Tai, Hoang Ốc, Kim Lâu Chi Tiết Nhất\",\"chuyenMuc\":\"Xem tuổi làm nhà\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"13/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tuổi Làm Nhà.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Quy chuẩn xem tuổi xây cất nhà cửa chuẩn phong thủy: Cách tránh 3 đại hạn Tam Tai, Kim Lâu, Hoang Ốc và thủ tục mượn tuổi làm nhà đắc tài lộc.\",\"noiDung\":\"\\u003ch3\\u003e1. Nguyên tắc chọn tuổi xây dựng nhà cửa\\u003c/h3\\u003e\\n      \\u003cp\\u003eLàm nhà là việc lớn liên quan đến sinh khí của cả dòng họ. Năm làm nhà của gia chủ phải đảm bảo không phạm phải 3 đại kỵ lớn: \\u003cstrong\\u003eTam Tai, Kim Lâu và Hoang Ốc\\u003c/strong\\u003e.\\u003c/p\\u003e\\n      \\n\\n      \\u003ch3\\u003e2. Chi tiết 3 hạn cần tránh\\u003c/h3\\u003e\\n      \\u003cul\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eTam Tai:\\u003c/strong\\u003e Cứ 12 năm sẽ có 3 năm Tam Tai liên tiếp đối với từng nhóm Tam Hợp. Khởi công năm Tam Tai dễ gặp trục trặc về sức khỏe và tài chính.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eKim Lâu:\\u003c/strong\\u003e Phân định rõ Kim Lâu Thân, Kim Lâu Thê, Kim Lâu Tử, Kim Lâu Súc.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eHoang Ốc:\\u003c/strong\\u003e Chia làm 6 cung: Nhất Cát (Tốt), Nhì Nghi (Tốt), Tam Địa Sát (Xấu), Tứ Tấn Tài (Tốt), Ngũ Thọ Tử (Xấu), Lục Hoang Ốc (Xấu). Khởi công cần chọn năm rơi vào \\u003cem\\u003eNhất Cát, Nhì Nghi, Tứ Tấn Tài\\u003c/em\\u003e.\\u003c/li\\u003e\\n      \\u003c/ul\\u003e\\n\\n      \\u003ch3\\u003e3. Giải pháp mượn tuổi khi gia chủ không hợp tuổi\\u003c/h3\\u003e\\n      \\u003cp\\u003eNếu bắt buộc phải xây nhà trong năm không được tuổi, gia chủ hoàn toàn có thể mượn tuổi của người thân lớn tuổi, khỏe mạnh, phúc đức vẹn toàn và được tuổi làm nhà trong năm đó để tiến hành động thổ.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"post-xem-tuoi-mua-nha\",\"tieuDe\":\"Xem Tuổi Mua Nhà: Chọn Năm Đắc Trạch Vượng Khí, An Cư Lập Nghiệp\",\"chuyenMuc\":\"Xem tuổi mua nhà\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"13/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tuổi Mua Nhà.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Khác biệt giữa xem tuổi xây nhà và mua nhà, cách chọn năm ký hợp đồng nhận nhà đắc vận tài lộc, gia tăng giá trị phong thủy bất động sản.\",\"noiDung\":\"\\u003ch3\\u003e1. Mua nhà có cần kiêng khem như xây nhà?\\u003c/h3\\u003e\\n      \\u003cp\\u003eNhiều gia chủ băn khoăn mua nhà sẵn có cần kiêng Kim Lâu, Hoang Ốc như động thổ xây mới hay không. Trong phong thủy, mua nhà thiên về giao dịch chuyển nhượng tài sản và tiếp nhận trường khí mới, do đó quan trọng nhất là trạch vận của ngôi nhà và tuổi người đứng tên ký hợp đồng.\\u003c/p\\u003e\\n      \\n\\n      \\u003ch3\\u003e2. Các tiêu chí chọn tuổi mua nhà đại cát\\u003c/h3\\u003e\\n      \\u003cul\\u003e\\n        \\u003cli\\u003eNăm mua nhà không phạm Thái Tuế hoặc xung chiếu trực tiếp với bản mệnh.\\u003c/li\\u003e\\n        \\u003cli\\u003eThời điểm ký hợp đồng nên chọn ngày Hoàng Đạo, có sao Thiên Mã, Lộc Mã trợ khí.\\u003c/li\\u003e\\n        \\u003cli\\u003eHướng của ngôi nhà cần hòa hợp với Cung Mệnh của gia chủ theo Bát Trạch Đông Tây Tứ Mệnh.\\u003c/li\\u003e\\n      \\u003c/ul\\u003e\\n\\n      \\u003ch3\\u003e3. Lễ nghi nhập trạch kích hoạt long mạch\\u003c/h3\\u003e\\n      \\u003cp\\u003eSau khi hoàn tất thủ tục mua nhà, việc chọn ngày lành tháng tốt làm lễ Nhập Trạch (về nhà mới) sẽ giúp tẩy trần uế khí và nghênh đón Thần Linh, Thổ Địa phù hộ độ trì.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"post-xem-tuoi-lam-an\",\"tieuDe\":\"Xem Tuổi Làm Ăn: Chọn Đối Tác Tương Sinh, Kinh Doanh Phát Đạt\",\"chuyenMuc\":\"Xem tuổi làm ăn\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"12/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tuổi Làm Ăn.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Cách phân tích mệnh số, cung phi và tính cách đối tác làm ăn giúp hợp tác lâu dài, buôn may bán đắt, mở rộng quy mô doanh nghiệp.\",\"noiDung\":\"\\u003ch3\\u003e1. Phong thủy trong hợp tác kinh doanh\\u003c/h3\\u003e\\n      \\u003cp\\u003eSự thành bại của một doanh nghiệp phụ thuộc rất lớn vào nhân sự lãnh đạo. Chọn người cộng sự hợp tuổi, tương sinh ngũ hành sẽ tạo nên sự đồng điệu về tư duy và bổ khuyết điểm yếu cho nhau.\\u003c/p\\u003e\\n      \\n\\n      \\u003ch3\\u003e2. Các tiêu chí thẩm định tuổi đối tác\\u003c/h3\\u003e\\n      \\u003cul\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eNgũ hành tương trợ:\\u003c/strong\\u003e Người mệnh Thổ hợp tác cùng mệnh Kim (Thổ sinh Kim), mệnh Hỏa hợp tác cùng mệnh Thổ... tạo dòng năng lượng tài lộc thông suốt.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eThiên can tương sinh:\\u003c/strong\\u003e Can là ngoại diện, phản ánh uy tín và giao tiếp xã hội. Thiên can tương hợp giúp công việc đàm phán hợp đồng luôn thuận buồm xuôi gió.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eĐịa chi tương hợp:\\u003c/strong\\u003e Tránh các tuổi phạm Tứ Hành Xung trong bộ sậu chủ chốt để hạn chế bất đồng nội bộ.\\u003c/li\\u003e\\n      \\u003c/ul\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"post-xem-huong-nha-hop-tuoi\",\"tieuDe\":\"Xem Hướng Nhà Hợp Tuổi Chuẩn Bát Trạch: Đón Sinh Khí Nghênh Phú Quý\",\"chuyenMuc\":\"Xem hướng nhà hợp tuổi\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"12/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Hướng Nhà Hợp Tuổi.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Hướng dẫn xác định Đông Tứ Trạch và Tây Tứ Trạch, phân định 4 cung cát (Sinh Khí, Diên Niên, Thiên Y, Phục Vị) và cách bố trí cửa chính chuẩn thước Lỗ Ban.\",\"noiDung\":\"\\u003ch3\\u003e1. Căn bản về Bát Trạch phong thủy\\u003c/h3\\u003e\\n      \\u003cp\\u003eMỗi con người khi sinh ra đều mang một Cung Mệnh (Quái Mệnh) thuộc một trong tám quẻ Càn, Khảm, Cấn, Chấn, Tốn, Ly, Khôn, Đoài. Từ đó phân chia thành hai nhóm lớn:\\u003c/p\\u003e\\n      \\n      \\u003cul\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eĐông Tứ Mệnh:\\u003c/strong\\u003e Hợp các hướng Đông Tứ Trạch (Đông, Đông Nam, Nam, Bắc).\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eTây Tứ Mệnh:\\u003c/strong\\u003e Hợp các hướng Tây Tứ Trạch (Tây, Tây Bắc, Tây Nam, Đông Bắc).\\u003c/li\\u003e\\n      \\u003c/ul\\u003e\\n\\n      \\u003ch3\\u003e2. Ý nghĩa 4 cung cát lành\\u003c/h3\\u003e\\n      \\u003cul\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eSinh Khí:\\u003c/strong\\u003e Đứng đầu về tài lộc, danh vọng và thăng tiến công danh sự nghiệp.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eThiên Y:\\u003c/strong\\u003e Chủ về sức khỏe trường thọ, gia đạo bình an, có quý nhân phù trợ.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eDiên Niên (Phước Đức):\\u003c/strong\\u003e Tốt cho các mối quan hệ tình cảm, vợ chồng hòa thuận.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003ePhục Vị:\\u003c/strong\\u003e Đem lại sự tĩnh tâm, củng cố năng lực học tập và tinh thần vững vàng.\\u003c/li\\u003e\\n      \\u003c/ul\\u003e\\n\\n      \\u003ch3\\u003e3. Cách hóa giải khi mua nhà không hợp hướng\\u003c/h3\\u003e\\n      \\u003cp\\u003eNếu hướng nhà phạm vào cung xấu (Tuyệt Mệnh, Họa Hại, Lục Sát, Ngũ Quỷ), gia chủ có thể hóa giải theo nguyên tắc: \\u003cem\\u003e\\\"Đa cát thắng tiểu hung\\\"\\u003c/em\\u003e qua hướng đặt bếp, bàn thờ hoặc sử dụng gương bát quái lồi phù hợp.\\u003c/p\\u003e\",\"updatedAt\":1792020983905}]",
    "TUONGSO_BAI_VIET_CUSTOM":  "[{\"id\":\"tuong-so-not-ruoi\",\"tieuDe\":\"Kinh nghiệm người xưa xem nốt ruồi Cát - Hung trên khuôn mặt\",\"chuyenMuc\":\"Xem Tướng Nốt Ruồi\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"02/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tướng Nốt Ruồi.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Dân gian có câu: \\u0027Nốt ruồi ẩn tàng là quý, nốt ruồi lộ liễu là hung\\u0027. Khám phá bản đồ định vị nốt ruồi phú quý thọ yểu trên gương mặt theo tướng pháp cổ truyền...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eTheo quan niệm cổ nhân, nốt ruồi trên khuôn mặt ví như cây cỏ trên núi, đồi son đất đỏ sinh cỏ thơm, núi cằn sỏi đá sinh cỏ dại. Nốt ruồi đen lánh như mun hoặc đỏ rực như chu sa, ẩn tàng ở nơi kín đáo (chân mày, dái tai, ấn đường) là biểu hiện của tài lộc và phúc đức trời ban.\\u003c/p\\u003e\\n\\u003ch3\\u003e1. Nốt ruồi cung Tài Bạch (Đầu mũi \\u0026 Cánh mũi)\\u003c/h3\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eMũi cai quản cung Tài Bạch. Đầu mũi có nốt ruồi son chủ về nguồn thu bất ngờ, tiền bạc hanh thông. Tuy nhiên nếu là nốt ruồi đen sạm nằm lộ thiên ngay chuẩn đầu hoặc cánh mũi thì cần cẩn trọng quản lý tài chính, tránh tiêu xài hoang phí.\\u003c/p\\u003e\\n\\u003ch3\\u003e2. Nốt ruồi trong lông mày (Thảo lý tàng châu)\\u003c/h3\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eNốt ruồi ẩn trong lông mày gọi là \\u0027Ngọc ẩn trong cỏ\\u0027. Đây là quý tướng bậc nhất, chủ về người túc trí đa mưu, có quý nhân phù trợ lúc nguy nan và hậu vận con cháu hiển đạt vinh hoa.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"tuong-so-ngu-quan\",\"tieuDe\":\"Tướng Pháp Cổ Truyền \\u0026 Ngũ Quan: Luận Khí Sắc \\u0026 Thần Khí Khuôn Mặt Đoán Vận Mệnh\",\"chuyenMuc\":\"Diện Tướng\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"01/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Ngũ Quan Luận Tướng.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Kinh nghiệm cổ nhân xem Ngũ Quan định phú quý thọ yểu: \\u0027Vấn phú tại tỵ, vấn quý tại nhãn, vấn phúc tại khẩu, vấn thọ tại nhĩ, vấn danh tại mi\\u0027...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eNăm cơ quan Mắt, Mũi, Miệng, Tai, Lông mày phản chiếu trọn vẹn khí chất và vận mệnh đời người. Quan sát Ngũ Quan phối hợp thần sắc giúp ta thấu suốt tâm can, đoán định thời vận cát hung.\\u003c/p\\u003e\\n\\u003ch3\\u003e1. Mắt (Giám Sát Quan)\\u003c/h3\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eMắt là cửa sổ tâm hồn, phản chiếu thần khí. Mắt sáng, tròng đen tròng trắng phân minh, ánh mắt nhìn thẳng từ tốn uy nghiêm là tướng đại quý nhân.\\u003c/p\\u003e\\n\\u003ch3\\u003e2. Mũi (Thẩm Biện Quan)\\u003c/h3\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eSống mũi thẳng tắp, không gồ ghề lộ xương, đầu mũi tròn trịa nở nang là kho vàng tích trữ của cải vững bền suốt đời.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"tuong-so-tam-dinh\",\"tieuDe\":\"Tam Đình Bình Đẳng: Luận Tiền Vận, Trung Vận \\u0026 Hậu Vận Khuôn Mặt\",\"chuyenMuc\":\"Tướng Mạo \\u0026 Tam Đình\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"30/08/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Tam Đình.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Người xưa chia khuôn mặt thành 3 phần: Thượng Đình (15-30 tuổi), Trung Đình (31-50 tuổi) và Hạ Đình (sau 50 tuổi) để đoán định vận trình tam thế...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eCổ nhân có câu: \\u0027Tam đình bình đẳng, nhất sinh y thực vô ưu\\u0027. Khuôn mặt có Tam Đình cân xứng, phân bố hài hòa, khí sắc sáng nhuận là biểu hiện của cuộc đời an định, gia đạo thuận hòa.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"tuong-so-chi-tay\",\"tieuDe\":\"Bí Truyền Thuật Xem Chỉ Tay: Luận Đoán 3 Đường Sinh Đạo, Trí Đạo \\u0026 Tâm Đạo\",\"chuyenMuc\":\"Xem Tướng Chỉ Tay\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"28/08/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tướng Chỉ Tay.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Giải mã bí ẩn các đường chỉ tay chính và các gò bàn tay. Phương pháp nhận biết đường quý nhân, đường định mệnh và dấu hiệu tiền bạc dồi dào...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eLòng bàn tay như mảnh đất trời ban, các đường chỉ tay tựa như sông ngòi khai thông sinh khí. Đường Sinh Đạo sâu dài, Trí Đạo rõ nét, Tâm Đạo ngay ngắn là tướng người trí tuệ hanh thông, trường thọ đại phúc.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"tuong-so-ca-dao\",\"tieuDe\":\"Ca Dao Tục Ngữ Người Xưa Xem Tướng: Đúc Kết Trí Tuệ Dân Gian\",\"chuyenMuc\":\"Ca Dao Tục Ngữ Xem Tướng\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"25/08/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Ca Dao Tục Ngữ Xem Tướng.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Tổng hợp các câu ca dao tục ngữ kinh điển về nhân tướng học: \\u0027Những người béo trục béo tròn\\u0027, \\u0027Đàn ông miệng rộng thì sang\\u0027 và bài học ứng xử cuộc đời...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eTrí tuệ dân gian ngàn đời đã đúc kết thuật xem tướng qua những vần thơ, câu ca dao mộc mạc mà vô cùng sâu sắc, giúp nhận diện tính cách và phẩm hạnh con người.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"tuong-so-tai-duc\",\"tieuDe\":\"Tướng Tự Tâm Sinh: Tâm Đức Cải Biến Tướng Mạo \\u0026 Số Mệnh\",\"chuyenMuc\":\"Khí Sắc \\u0026 Thần Khí\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"20/08/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Tướng Khí Qua Cử Chỉ Âm Thanh.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Cổ nhân dạy: \\u0027Hữu tâm vô tướng, tướng tự tâm sinh; Hữu tướng vô tâm, tướng tùy tâm diệt\\u0027. Sức mạnh của sự tu dưỡng cải biến vận mệnh...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eHình tướng bên ngoài chỉ là tấm gương phản chiếu tâm thức bên trong. Nuôi dưỡng lòng từ bi, hành thiện tích đức chính là phương thuốc tối thượng chuyển hung hóa cát, làm cho diện mạo ngày càng phúc hậu sáng ngời.\\u003c/p\\u003e\",\"updatedAt\":1792020983905}]",
    "TAMLINH_BAI_VIET_CUSTOM":  "[{\"id\":\"lenghi-cam-nang-co-truyen\",\"tieuDe\":\"Nghi Lễ Cổ Truyền \\u0026 Văn Khấn Toàn Tập: Cẩm Nang Bách Gia Chiêm Bái\",\"chuyenMuc\":\"Văn Khấn\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"06/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Cẩm Nang Lễ Nghi Cổ Truyền Việt Nam.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Tổng hợp bài văn khấn mùng 1, ngày rằm, lễ tết, động thổ, nhập trạch, tạ mộ chuẩn mực cổ truyền...\",\"noiDung\":\"\\u003cp\\u003eVăn khấn cổ truyền là cầu nối tâm linh giữa con cháu với tổ tiên nguồn cội và chư vị thần linh cai quản bản thổ.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"tamlinh-thau-suot-nhan-qua\",\"tieuDe\":\"Thấu Suốt Luật Nhân Quả: Gieo Mầm Thiện Đạo, Gặt Hái Phúc Lành Trọn Đời\",\"chuyenMuc\":\"Tín Ngưỡng Dân Gian\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"04/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Thấu Suốt Tam Linh Phương Đông.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Luật Nhân Quả không trừ một ai. Thấu hiểu lẽ công bằng của đất trời để sống đời thiện lương, thanh thản...\",\"noiDung\":\"\\u003cp\\u003eNhân quả như bóng theo hình. Muốn gặt quả ngọt ắt phải gieo hạt giống lành từ suy nghĩ, lời nói đến hành động mỗi ngày.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"post-a-diem-bao-tu-dong-vat-mum4nerx\",\"tieuDe\":\"Điềm Báo Dân Gian Từ Loài Vật: Giải Mã Hiện Tượng Chim Sa Cá Nhảy\",\"chuyenMuc\":\"Điềm Báo Dân Gian\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"10/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Điềm Báo Dân Gian.jpeg\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Khám phá các quan niệm dân gian về điềm báo khi động vật xuất hiện bất thường trong nhà...\",\"noiDung\":\"\\u003cp\\u003eTrong văn hóa dân gian, sự xuất hiện hoặc hành vi bất thường của các loài động vật đôi khi được xem là những dấu hiệu mang thông điệp từ tự nhiên. Người xưa quan sát thiên tượng và hành vi muôn loài để dự đoán thời tiết, điềm may hay điều cần đề phòng cẩn trọng.\\u003c/p\\u003e\\n\\n\\u003ch3\\u003e1. Giải mã các hiện tượng động vật báo điềm lành\\u003c/h3\\u003e\\n\\u003cp\\u003e• \\u003cstrong\\u003eChim én, chim sẻ làm tổ trong nhà:\\u003c/strong\\u003e Tượng trưng cho phong thủy đất lành chim đậu, gia đạo hưng thịnh, sắp có tin vui về hôn sự hoặc tài lộc.\\u003c/p\\u003e\\n\\u003cp\\u003e• \\u003cstrong\\u003eOng vào nhà làm tổ:\\u003c/strong\\u003e Ong mang năng lượng Dương khí dồi dào, báo hiệu tài vận hanh thông, công việc kinh doanh khởi sắc rực rỡ.\\u003c/p\\u003e\\n\\u003cp\\u003e• \\u003cstrong\\u003eRùa bò vào nhà:\\u003c/strong\\u003e Rùa là linh vật trong Tứ Linh (Quy), chủ về sự trường thọ, bền vững và quý nhân phù trợ che chở.\\u003c/p\\u003e\\n\\u003ch3\\u003e2. Các hiện tượng cần lưu tâm cẩn trọng\\u003c/h3\\u003e\\n\\u003cp\\u003e• \\u003cstrong\\u003eHiện tượng \\u0027Chim sa cá nhảy\\u0027:\\u003c/strong\\u003e Cổ nhân nhắc nhở khi gặp chim rơi hoặc cá nhảy lên thuyền/nhà nên cẩn trọng việc xuất hành, đi xa hoặc giao dịch tiền bạc lớn trong vài ngày tới.\\u003c/p\\u003e\\n\\u003cp\\u003e• \\u003cstrong\\u003eChó sủa liên tục vào khoảng không:\\u003c/strong\\u003e Thường do trường năng lượng bị xáo trộn hoặc thời tiết thay đổi đột ngột, nên giữ bình tĩnh, kiểm tra cửa nẻo chu đáo.\\u003c/p\\u003e\\n\\u003ch3\\u003e3. Thái độ đúng đắn trước các điềm báo\\u003c/h3\\u003e\\n\\u003cp\\u003eĐiềm báo chỉ mang tính chất nhắc nhở con người sống cẩn trọng, tỉnh táo hơn. Giữ tâm thái hướng thiện, không hoang mang lo sợ vô căn cứ chính là phương pháp hóa giải mọi điềm báo tốt nhất.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"post-bi-an-qua-giac-mo-muobm08z\",\"tieuDe\":\"Bí Ẩn Điềm Báo Giấc Mơ: Chiêm Bao \\u0026 Những Thông Điệp Từ Tiềm Thức\",\"chuyenMuc\":\"Chuyện Tâm Linh\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"08/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Giải Mã Giấc Mơ.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Giải mã các giấc mơ thường gặp: mơ thấy lửa, nước, bay lượn, người thân quá vãng...\",\"noiDung\":\"\\u003cp\\u003eGiấc mơ là tấm gương phản chiếu nội tâm và tiềm thức, đôi khi chứa đựng linh cảm đặc biệt về tương lai.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"khoahoc-huyen-hoc-chuyen-sau\",\"tieuDe\":\"Khóa Học Thuật Số Huyền Học: Hệ Thống Luận Giải Tử Vi Đẩu Số, Kinh Dịch \\u0026 Bát Trạch\",\"chuyenMuc\":\"Khóa Học\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"15/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Khóa Học Huyền Học Chuyên Sâu.png\",\"noiBat\":true,\"uuTienFeed\":3,\"tomTat\":\"Chương trình đào tạo thuật số bài bản từ căn bản đến nâng cao: Nắm vững tinh tú Tử Vi, 64 quẻ Kinh Dịch lục hào, nguyên lý phong thủy Loan Đầu - Lý Khí, trực tiếp hướng dẫn bởi Thầy Duy Tâm Phúc.\",\"noiDung\":\"\\u003ch3\\u003e1. Giới thiệu chương trình học thuật số toàn diện\\u003c/h3\\u003e\\n\\u003cp\\u003eKhóa học được thiết kế khoa học, kết hợp giữa lý thuyết nguyên bản từ các cổ thư kinh điển (Tử Vi Đẩu Số Toàn Thư, Dịch Học Tinh Hoa, Thẩm Thị Huyền Không Học) và kinh nghiệm thực chiến hàng ngàn lá số của Viện Nghiên Cứu Thuật Số.\\u003c/p\\u003e\\n\\n\\u003ch3\\u003e2. Lộ trình đào tạo 3 cấp độ\\u003c/h3\\u003e\\n\\u003cul\\u003e\\n\\u003cli\\u003e\\u003cstrong\\u003eCấp độ 1 - Căn Bản (Lý Thuyết Âm Dương Ngũ Hành):\\u003c/strong\\u003e Nắm vững Can Chi, Nạp Giáp, Cung Vị, 14 Chính Tinh và Tứ Hóa.\\u003c/li\\u003e\\n\\u003cli\\u003e\\u003cstrong\\u003eCấp độ 2 - Thực Chiến (Luận Đoán Đại Vận - Tiểu Hạn):\\u003c/strong\\u003e Kỹ năng bóc tách lá số, luận giải đa chiều Mệnh - Tài - Quan - Di, phương pháp gieo quẻ Dịch Lục Hào giải đoán sự việc.\\u003c/li\\u003e\\n\\u003cli\\u003e\\u003cstrong\\u003eCấp độ 3 - Ứng Dụng (Cố Vấn \\u0026 Cải Vận):\\u003c/strong\\u003e Ứng dụng Bát Trạch - Huyền Không Phi Tinh, hóa giải cung xấu, kích hoạt cung tài lộc cho gia trạch và doanh nghiệp.\\u003c/li\\u003e\\n\\u003c/ul\\u003e\\n\\u003ch3\\u003e3. Quyền lợi học viên\\u003c/h3\\u003e\\n\\u003cp\\u003eHọc viên được cấp tài liệu nội bộ độc quyền, tham gia nhóm đàm đạo chuyên sâu và được Thầy Duy Tâm Phúc trực tiếp chấm bài, giải đáp các ca luận giải thực tế.\\u003c/p\\u003e\"},{\"id\":\"diendan-dam-dao-ly-so\",\"tieuDe\":\"Diễn Đàn Đàm Đạo Lý Số: Không Gian Trao Đổi Tri Thức \\u0026 Luận Giải Vận Mệnh Cùng Thầy Duy Tâm Phúc\",\"chuyenMuc\":\"Diễn Đàn\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"15/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Diễn Đàn Thuật Số.png\",\"noiBat\":true,\"uuTienFeed\":4,\"tomTat\":\"Không gian mở kết nối cộng đồng người đam mê thuật số Đông phương: Nơi chia sẻ các cách cục kỳ cách, phân tích nghiệm lý lá số thực tế, đặt câu hỏi giao lưu học thuật và nhận phản hồi trực tiếp từ chuyên gia.\",\"noiDung\":\"\\u003ch3\\u003e1. Tinh thần của Diễn Đàn Thuật Số\\u003c/h3\\u003e\\n\\u003cp\\u003eDiễn đàn là nhịp cầu văn hóa học thuật, quy tụ đông đảo học viên, nhà nghiên cứu và những người yêu thích triết lý mệnh lý phương Đông trên khắp cả nước. Tiêu chí hàng đầu của diễn đàn là: \\u003cem\\u003eBiện chứng - Khách quan - Nhân văn - Văn minh\\u003c/em\\u003e.\\u003c/p\\u003e\\n\\n\\u003ch3\\u003e2. Các chủ đề trao đổi sôi nổi hàng tuần\\u003c/h3\\u003e\\n\\u003cul\\u003e\\n\\u003cli\\u003e\\u003cstrong\\u003eLuận giải lá số tuần tra cứu:\\u003c/strong\\u003e Phân tích các trường hợp đặc biệt: Mệnh vô chính diệu, Sát Phá Tham, Cơ Nguyệt Đồng Lương ngộ Triệt Tuần.\\u003c/li\\u003e\\n\\u003cli\\u003e\\u003cstrong\\u003eGóc nghiệm chứng quẻ Dịch:\\u003c/strong\\u003e Chia sẻ nhật ký bốc quẻ thi cử, kinh doanh, xuất hành và đối chiếu kết quả thực tế.\\u003c/li\\u003e\\n\\u003cli\\u003e\\u003cstrong\\u003eTọa đàm trực tuyến cùng Thầy Duy Tâm Phúc:\\u003c/strong\\u003e Định kỳ giải đáp thắc mắc chuyên sâu và hướng dẫn phương pháp hóa giải xung sát.\\u003c/li\\u003e\\n\\u003c/ul\\u003e\\n\\u003ch3\\u003e3. Quy tắc tham gia diễn đàn\\u003c/h3\\u003e\\n\\u003cp\\u003eThành viên tham gia tôn trọng sự đa dạng của các trường phái học thuật, tuyệt đối không tuyên truyền mê tín tà đạo, giữ gìn ngôn phong lịch thiệp và cùng nhau gìn giữ nét đẹp văn hóa truyền thống.\\u003c/p\\u003e\"}]",
    "BAI_VIET_CHUYEN_MUC_CUSTOM":  "[{\"timestamp\":1792143478469,\"timeFormatted\":\"16/10/2026 - 16:37:58\",\"id\":\"tuvi-post-ban-ve-sao-khong-kiep-mvary3y7\",\"tieuDe\":\"Bàn Về Sao Không Kiếp\",\"chuyenMuc\":\"Tử Vi Đẩu Số\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"16/10/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Sao Địa Không - Địa Kiếp.jpeg\",\"tomTat\":\"Trong Tử Vi Đẩu Số, Không Kiếp là cách gọi chung của hai sát tinh Địa Không và Địa Kiếp. Đây là hai ngôi sao mang tính chất biến động mạnh, thường gắn với sự phá cách, thăng trầm, ...\",\"noiDung\":\"\\u003ch2 data-pm-slice=\\\"1 3 []\\\" style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e1. Khái quát về sao Không Kiếp\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eTrong Tử Vi Đẩu Số, Không Kiếp là cách gọi chung của hai sát tinh \\u003cstrong\\u003eĐịa Không và Địa Kiếp\\u003c/strong\\u003e. Đây là hai ngôi sao mang tính chất biến động mạnh, thường gắn với sự phá cách, thăng trầm, bất ngờ và những bước ngoặt lớn trong cuộc đời con người.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eĐịa Không và Địa Kiếp thuộc nhóm sao có tính chất đặc biệt, không hoàn toàn giống những sát tinh chủ về hình thương hay tranh chấp. Bộ sao này thường biểu hiện sự thay đổi đột ngột trong tư duy, hoàn cảnh sống, công danh, tài lộc và các mối quan hệ. Khi hội hợp với những cát tinh, người có Không Kiếp có thể bộc lộ năng lực khác thường, tư duy vượt khuôn khổ và khả năng tạo dựng thành tựu từ những hoàn cảnh khó khăn. Ngược lại, khi gặp nhiều hung sát tinh hoặc rơi vào vị trí bất lợi, chúng có thể làm gia tăng sự bất ổn, tổn thất và những biến cố khó lường.\\u003c/p\\u003e\\u003ch2 style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e2. Ý nghĩa sao Địa Không\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eĐịa Không thường được luận theo tính chất hư không, phá cách, tư tưởng khác biệt và khả năng nhìn ra những điều nằm ngoài khuôn mẫu thông thường. Người có Địa Không thủ Mệnh hoặc hội chiếu có thể có tư duy nhanh nhạy, thích tìm tòi, không dễ chấp nhận những quan niệm cứng nhắc.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eTuy nhiên, mặt trái của Địa Không là tính thiếu ổn định, dễ thay đổi mục tiêu hoặc có lúc suy tính nhiều nhưng kết quả không như mong muốn. Trong công việc và tài chính, sao này thường được xem là dấu hiệu cần chú ý đến những quyết định bất ngờ, kế hoạch thiếu chắc chắn và nguy cơ mất mát khi quá chủ quan.\\u003c/p\\u003e\\u003ch2 style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e3. Ý nghĩa sao Địa Kiếp\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eĐịa Kiếp mang sắc thái biến động, đột phá và những sự việc xảy ra ngoài dự liệu. Trong cách luận truyền thống, sao này thường được liên hệ với sự hao tổn, trở ngại, rủi ro hoặc những bước ngoặt buộc con người phải thay đổi hướng đi.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eỞ mặt tích cực, Địa Kiếp cũng có thể biểu hiện tinh thần quyết liệt, khả năng hành động trong hoàn cảnh khó khăn và xu hướng dám làm những việc người khác ngần ngại. Khi được các sao tốt hỗ trợ, người có Địa Kiếp có thể chuyển hóa trải nghiệm bất lợi thành kinh nghiệm, từ đó trưởng thành và có bản lĩnh hơn.\\u003c/p\\u003e\\u003ch2 style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e4. Không Kiếp tại cung Mệnh\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eKhi Địa Không và Địa Kiếp đóng tại hoặc hội chiếu cung Mệnh, cần xem xét toàn bộ bố cục lá số thay vì chỉ căn cứ vào hai sao này để kết luận tốt xấu.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eNgười có cách cục Không Kiếp thường được luận là có cuộc đời nhiều biến chuyển, tính cách khó đoán hoặc không thích đi theo con đường thông thường. Có người trải qua những giai đoạn thăng trầm rõ rệt, nhưng cũng có người nhờ tư duy khác biệt và sự quyết đoán mà tạo dựng được hướng đi riêng.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eĐiều quan trọng là phải xét thêm chính tinh thủ Mệnh, cung Thân, tam phương tứ chính, các sao hội hợp và vận hạn. Không Kiếp không đồng nghĩa với thất bại hay số phận bất hạnh; ý nghĩa cụ thể phụ thuộc vào toàn bộ lá số.\\u003c/p\\u003e\\u003ch2 style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e5. Không Kiếp trong công danh và tài lộc\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eTrong phương diện công danh, Không Kiếp thường được liên hệ với những bước ngoặt nghề nghiệp, sự thay đổi môi trường làm việc hoặc con đường phát triển không theo lối mòn. Người có bộ sao này cần chú trọng tính ổn định, kế hoạch dài hạn và khả năng kiểm soát rủi ro.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eVề tài lộc, Không Kiếp thường được xem là bộ sao cần thận trọng khi đầu tư, kinh doanh hoặc quyết định những khoản tiền lớn. Đặc biệt, không nên vì lợi ích trước mắt mà bỏ qua việc kiểm chứng thông tin và đánh giá khả năng thua lỗ. Khi có các sao tài lộc, quyền tinh và cát tinh hỗ trợ, vẫn cần xét sự phối hợp giữa các sao để luận đoán mức độ thuận lợi.\\u003c/p\\u003e\\u003ch2 style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e6. Cách luận giải Không Kiếp chính xác\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eMuốn luận giải Địa Không và Địa Kiếp, cần chú ý các yếu tố sau:\\u003c/p\\u003e\\u003cul data-spread=\\\"false\\\"\\u003e\\u003cli style=\\\"line-height: 1.65; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-size: 14px; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; font-weight: normal;\\\"\\u003e\\u003cp style=\\\"font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-weight: normal;\\\"\\u003e\\u003cstrong\\u003eVị trí đóng sao:\\u003c/strong\\u003e Xét Không Kiếp tại cung Mệnh, Thân, Quan Lộc, Tài Bạch, Điền Trạch hay các cung khác.\\u003c/p\\u003e\\u003c/li\\u003e\\u003cli style=\\\"line-height: 1.65; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-size: 14px; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; font-weight: normal;\\\"\\u003e\\u003cp style=\\\"font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-weight: normal;\\\"\\u003e\\u003cstrong\\u003eChính tinh đồng cung:\\u003c/strong\\u003e Xem Không Kiếp kết hợp với Tử Vi, Thiên Phủ, Thiên Tướng, Thất Sát, Phá Quân và những chính tinh khác như thế nào.\\u003c/p\\u003e\\u003c/li\\u003e\\u003cli style=\\\"line-height: 1.65; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-size: 14px; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; font-weight: normal;\\\"\\u003e\\u003cp style=\\\"font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-weight: normal;\\\"\\u003e\\u003cstrong\\u003eCát tinh và hung tinh:\\u003c/strong\\u003e Đánh giá các sao hội hợp, sự hỗ trợ hoặc gia tăng tính chất bất lợi của bộ Không Kiếp.\\u003c/p\\u003e\\u003c/li\\u003e\\u003cli style=\\\"line-height: 1.65; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-size: 14px; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; font-weight: normal;\\\"\\u003e\\u003cp style=\\\"font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-weight: normal;\\\"\\u003e\\u003cstrong\\u003eĐại hạn và tiểu hạn:\\u003c/strong\\u003e Xem xét thời điểm các sao tác động, tránh lấy một cách cục cố định để kết luận toàn bộ cuộc đời.\\u003c/p\\u003e\\u003c/li\\u003e\\u003cli style=\\\"line-height: 1.65; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-size: 14px; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; font-weight: normal;\\\"\\u003e\\u003cp style=\\\"font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-weight: normal;\\\"\\u003e\\u003cstrong\\u003eSự cân bằng của lá số:\\u003c/strong\\u003e Phải luận tổng thể cung Mệnh, cung Thân, tam phương tứ chính và các cung liên quan.\\u003c/p\\u003e\\u003c/li\\u003e\\u003c/ul\\u003e\",\"noiBat\":true,\"uuTienFeed\":1,\"updatedAt\":1795000000000},{\"id\":\"tuvi-ngay-12-con-giap\",\"tieuDe\":\"Tử Vi Hôm Nay: Luận Đoán Cát Hung 12 Con Giáp \\u0026 Giờ Hoàng Đạo Khởi Sự\",\"chuyenMuc\":\"Xem tử vi hàng ngày\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"15/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tử Vi Hàng Ngày.jpeg\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Dự báo chi tiết vận trình công danh, tài lộc, tình duyên của 12 con giáp trong ngày hôm nay. Hướng dẫn chọn khung giờ đại cát và hướng xuất hành nghênh tiếp Hỷ Thần, Tài Thần.\",\"noiDung\":\"\\n      \\u003cp style=\\\"font-size: 15.5px; line-height: 1.8; color: #2C241E; margin-bottom: 18px; text-align: justify;\\\"\\u003e\\n        \\u003cstrong\\u003eTử vi hàng ngày\\u003c/strong\\u003e là nội dung giúp bạn tham khảo những xu hướng và diễn biến nổi bật có thể xảy ra trong một ngày cụ thể dựa trên \\u003cstrong\\u003enăm sinh\\u003c/strong\\u003e, \\u003cstrong\\u003egiới tính\\u003c/strong\\u003e và \\u003cstrong\\u003engày Can Chi được lựa chọn\\u003c/strong\\u003e. Khác với việc xem tổng quan vận mệnh cả đời, tử vi hàng ngày tập trung vào trường khí của từng ngày, từ đó đưa ra những thông tin tham khảo về công việc, tài lộc, tình cảm, gia đạo, sức khỏe và các hoạt động nên thực hiện hoặc cần lưu ý. Khi xem tử vi hàng ngày, hệ thống sẽ kết hợp nhiều yếu tố như \\u003cstrong\\u003eCan Chi năm sinh\\u003c/strong\\u003e, \\u003cstrong\\u003engũ hành bản mệnh\\u003c/strong\\u003e, trường khí Can Chi của ngày để đưa ra lời khuyên phù hợp nhất.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e1. Tổng quan trường khí và cục diện cát hung ngày hôm nay\\u003c/h3\\u003e\\n      \\u003cp\\u003eTrong thuật số tử vi, vận trình mỗi ngày chịu ảnh hưởng sâu sắc bởi sự vận hành của Thiên Can, Địa Chi và hệ sao Lưu Nhật. Ngày hôm nay mang trường khí cân bằng, rất thích hợp cho việc mưu cầu công việc, ký kết giấy tờ hợp đồng hoặc bàn bạc kế hoạch kinh doanh lâu dài.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e2. Dự đoán vận thế từng nhóm tuổi tiêu biểu\\u003c/h3\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Nhóm tuổi Tý - Thìn - Thân (Tam Hợp Thủy Cục):\\u003c/strong\\u003e Có quý nhân tương trợ, công việc hành thông suôn sẻ. Tài lộc khởi sắc vào buổi chiều, thích hợp thu hồi nợ đọng hoặc giao dịch quan trọng.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Nhóm tuổi Dần - Ngọ - Tuất (Tam Hợp Hỏa Cục):\\u003c/strong\\u003e Tinh thần phấn chấn, có nhiều sáng kiến đột phá. Tuy nhiên cần chú ý lời ăn tiếng nói, tránh nóng nảy trong các cuộc họp mặt giao lưu.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Nhóm tuổi Tỵ - Dậu - Sửu (Tam Hợp Kim Cục):\\u003c/strong\\u003e Vận trình tài chính ổn định, có lộc ăn uống hoặc quà tặng từ đối tác. Gia đạo bình an hòa thuận.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Nhóm tuổi Hợi - Mão - Mùi (Tam Hợp Mộc Cục):\\u003c/strong\\u003e Khởi sắc về mặt tình duyên và quan hệ xã giao. Người độc thân có cơ hội gặp gỡ đối tượng tâm đầu ý hợp.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e3. Bảng giờ hoàng đạo đại cát trong ngày\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eGiờ Mão (05h - 07h):\\u003c/strong\\u003e Ngọc Đường Hoàng Đạo – Cát lợi cho việc dâng hương, khai trương mở hàng.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eGiờ Tỵ (09h - 11h):\\u003c/strong\\u003e Tư Mệnh Hoàng Đạo – Cực tốt cho việc ký kết hợp đồng, gặp gỡ đối tác quý nhân.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eGiờ Thân (15h - 17h):\\u003c/strong\\u003e Thanh Long Hoàng Đạo – Thuận lợi cầu tài lộc, xuất hành đi xa an toàn như ý.\\u003c/p\\u003e\\n    \"},{\"id\":\"tuvi-tuan-chuyen-bien-tai-loc\",\"tieuDe\":\"Tử Vi Tuần Mới: Chuyển Biến Cung Tài Bạch \\u0026 Sự Nghiệp 12 Tuổi\",\"chuyenMuc\":\"Xem tử vi hàng tuần\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"14/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tử Vi Theo Tuần.png\",\"noiBat\":false,\"uuTienFeed\":2,\"tomTat\":\"Khám phá diễn biến vận hạn trong 7 ngày tới. Nhận diện các cung hoàng đạo và tuổi gặp vận quý nhân dẫn lối, cũng như các lưu ý phong thủy để bảo toàn nguồn tài chính.\",\"noiDung\":\"\\u003ch3\\u003e1. Bức tranh vận trình tuần mới tổng quát\\u003c/h3\\u003e\\n      \\u003cp\\u003eBước sang tuần mới, vầng nhật nguyệt hội tụ nhiều cát tinh mang lại năng lượng chuyển mình tích cực. Những ai đang ấp ủ dự án mới nên nhanh chóng triển khai vào đầu tuần (từ Thứ Hai đến Thứ Tư) để nắm trọn thiên thời địa lợi.\\u003c/p\\u003e\\n\\n      \\n\\n      \\u003ch3\\u003e2. Điểm sáng tài lộc và sự nghiệp\\u003c/h3\\u003e\\n      \\u003cp\\u003eNhững bản mệnh mang hành Thổ và Kim sẽ đón nhận nhiều vận may bất ngờ về tiền bạc trong tuần này. Khoản thu phụ từ công việc tự do hoặc đầu tư tay trái có xu hướng gia tăng đáng kể.\\u003c/p\\u003e\\n      \\u003cp\\u003eĐối với chốn công sở, sự hòa nhã và thấu hiểu đồng nghiệp sẽ giúp bạn giải tỏa được các khúc mắc tồn đọng từ tuần trước, tạo tiền đề vững chắc cho việc thăng quan tiến chức.\\u003c/p\\u003e\"},{\"id\":\"tuvi-thang-nguyet-lenh\",\"tieuDe\":\"Tử Vi Tháng Này: Dự Đoán Vượng Suy Tài Vận Theo Lịch Nguyệt Lệnh\",\"chuyenMuc\":\"Xem tử vi hàng tháng\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"10/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tử Vi Theo Tháng.jpeg\",\"noiBat\":false,\"uuTienFeed\":3,\"tomTat\":\"Cẩm nang dự báo xu thế tháng theo chu kỳ tiết khí và tiết lệnh. Hướng dẫn các phương thức kích hoạt tài lộc, bình ổn gia đạo và phòng ngừa hao tán tiền của.\",\"noiDung\":\"\\n      \\u003cp style=\\\"font-size: 15.5px; line-height: 1.8; color: #2C241E; margin-bottom: 18px; text-align: justify;\\\"\\u003e\\n        \\u003cstrong\\u003eTử vi theo tháng\\u003c/strong\\u003e giúp bạn nắm bắt được những xu hướng nổi bật trong từng tháng của năm, từ đó có sự chuẩn bị tốt hơn trong công việc, tài chính, tình cảm và sức khỏe để mỗi tháng đều là một khởi đầu tốt đẹp.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e1. Quy luật nguyệt lệnh chi phối vận hạn tháng\\u003c/h3\\u003e\\n      \\u003cp\\u003eMỗi tháng âm lịch đại diện cho một mùa khí và vị trí tinh tú riêng biệt. Khi sao Lưu Nguyệt di chuyển qua các cung vị trên lá số tử vi cá nhân, nó sẽ kích hoạt các sự kiện trọng đại về sức khỏe, điền sản, gia quyến.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e2. Các lưu ý trọng yếu trong tháng\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eVề phương diện sức khỏe:\\u003c/strong\\u003e Tiết trời giao hòa dễ gây ra bệnh đường hô hấp hoặc đau mỏi gân cốt. Cần chú trọng chế độ ẩm thực thanh đạm và nghỉ ngơi điều độ.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eVề đầu tư kinh doanh:\\u003c/strong\\u003e Tránh các thương vụ mang tính chất rủi ro cao hoặc đầu cơ lướt sóng. Hãy tập trung củng cố nền tảng tài chính hiện có.\\u003c/p\\u003e\\n    \"},{\"id\":\"tuvi-tron-doi-giai-ma-menh-than\",\"tieuDe\":\"Tử Vi Trọn Đời: Giải Mã Bản Đồ Định Mệnh Qua Cung Mệnh \\u0026 Cung Thân\",\"chuyenMuc\":\"Xem tử vi trọn đời\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"08/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Tử Vi Cung Mệnh Cung Thân.png\",\"noiBat\":true,\"uuTienFeed\":4,\"tomTat\":\"Khám phá cấu trúc cốt lõi của lá số tử vi trọn đời. Phân tích mối tương quan giữa cung Mệnh (tiền định) và cung Thân (hậu thiên lập nghiệp) quyết định họa phúc một kiếp người.\",\"noiDung\":\"\\u003ch3\\u003e1. Cung Mệnh và Cung Thân: Gốc rễ của số phận\\u003c/h3\\u003e\\n      \\u003cp\\u003eTrong nghệ thuật dự trắc Tử Vi Đẩu Số, \\u003cstrong\\u003eCung Mệnh\\u003c/strong\\u003e được coi là gốc rễ, thể hiện hình hài, cốt cách, tính cách thiên bẩm và vận mệnh nửa đầu cuộc đời (từ nhỏ đến khoảng 30 - 32 tuổi). Trong khi đó, \\u003cstrong\\u003eCung Thân\\u003c/strong\\u003e là nơi nương tựa của hậu thiên, phản ánh hành động, nỗ lực cá nhân và giai đoạn từ tuổi trung niên trở về già.\\u003c/p\\u003e\\n\\n      \\n\\n      \\u003ch3\\u003e2. Mối quan hệ giữa Cung Mệnh và Ngũ Hành Bản Mệnh\\u003c/h3\\u003e\\n      \\u003cp\\u003eMột lá số thượng cách khi Ngũ Hành của bản mệnh tương sinh hoặc tỷ hòa với Ngũ Hành của vị trí cung an Mệnh. Ví dụ: Người mệnh Hỏa cư tại cung Dần, Mão (Mộc) gọi là Mộc sinh Hỏa, suốt đời dễ gặp hoàn cảnh tương trợ, gặp nguy hóa an.\\u003c/p\\u003e\\n      \\n      \\u003ch3\\u003e3. Lời khuyên tu tâm dưỡng tính cải mệnh\\u003c/h3\\u003e\\n      \\u003cblockquote\\u003e\\\"Đức năng thắng số - Nhân định thắng thiên. Lá số tử vi chỉ ra khuynh hướng của vũ trụ, nhưng cách lựa chọn, sự tích đức hành thiện và nghị lực bản thân mới là yếu tố quyết định nấc thang thành tựu cuối cùng.\\\"\\u003c/blockquote\\u003e\"},{\"id\":\"tuvi-van-han-dai-van-tieu-han\",\"tieuDe\":\"Xem Vận Hạn Tử Vi: Cách Tính Đại Vận 10 Năm \\u0026 Hóa Giải Sát Tinh Cung Hạn\",\"chuyenMuc\":\"Xem vận hạn tử vi\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"05/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Vận Hạn Tử Vi.png\",\"noiBat\":false,\"uuTienFeed\":5,\"tomTat\":\"Hướng dẫn nhận diện chu kỳ Đại Hạn 10 năm và Tiểu Hạn hàng năm. Phương pháp ứng phó và hóa giải khi gặp các sao sát tinh như Hóa Kỵ, Kình Dương, Đà La, Không Kiếp.\",\"noiDung\":\"\\u003ch3\\u003e1. Cơ chế vận hành của Đại Vận và Lưu Niên Tiểu Hạn\\u003c/h3\\u003e\\n      \\u003cp\\u003eMột đời người trải qua nhiều chu kỳ Đại Vận 10 năm. Tùy theo Cục số (Thủy Nhị Cục, Mộc Tam Cục, Kim Tứ Cục, Thổ Ngũ Cục, Hỏa Lục Cục) mà tuổi bắt đầu bước vào Đại Vận sẽ rơi vào 2, 3, 4, 5 hoặc 6 tuổi.\\u003c/p\\u003e\\n\\n      \\n\\n      \\u003ch3\\u003e2. Nhận diện các sao hung sát tinh thường gặp\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eKình Dương - Đà La:\\u003c/strong\\u003e Đại diện cho chông gai, trở ngại, thị phi kiện tụng hoặc phẫu thuật thương tật.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eHỏa Tinh - Linh Tinh:\\u003c/strong\\u003e Kích phát tính nóng nảy, bất ngờ gặp biến cố hoặc hao tốn công sức.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eĐịa Không - Địa Kiếp:\\u003c/strong\\u003e Tượng trưng cho sự mất mát tài chính bất ngờ, mưu sự khó thành nếu tâm cơ quá cao.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eHóa Kỵ:\\u003c/strong\\u003e Sao của sự nghi kỵ, ghen ghét và cản trở tiến trình công danh.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e3. Bí quyết chuyển hóa hung hiểm\\u003c/h3\\u003e\\n      \\u003cp\\u003eKhi bước vào cung hạn gặp sát tinh, cổ nhân khuyên nên \\\"Tĩnh dĩ đãi động\\\" (giữ tâm thái tĩnh lặng, cẩn trọng trong từng bước đi). Tăng cường bố thí, hành thiện, giữ gìn chữ tín và cẩn trọng giấy tờ là liều thuốc hữu hiệu nhất để biến hung thành cát.\\u003c/p\\u003e\"},{\"id\":\"tuvi-can-xuong-tinh-cot\",\"tieuDe\":\"Cân Xương Đoán Số: Bảng Tra Cân Xương Tính Cốt \\u0026 Giải Mã Lượng Chỉ Cuộc Đời\",\"chuyenMuc\":\"Cân xương đoán số\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"02/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Cân Xương Đoán Số.png\",\"noiBat\":false,\"uuTienFeed\":6,\"tomTat\":\"Phương pháp Cân Xương Tính Cốt trứ danh của Lão Tử và Viên Thiên Cang. Hướng dẫn tính tổng lượng chỉ Năm - Tháng - Ngày - Giờ sinh và tra cứu bài thơ định mệnh chuẩn xác.\",\"noiDung\":\"\\n      \\u003cp style=\\\"font-size: 15.5px; line-height: 1.8; color: #2C241E; margin-bottom: 18px; text-align: justify;\\\"\\u003e\\n        \\u003cstrong\\u003eCân xương đoán số\\u003c/strong\\u003e (còn gọi là \\u003cstrong\\u003eCân Xương Tính Cốt\\u003c/strong\\u003e hay \\u003cstrong\\u003eLượng Chỉ Đoán Mệnh\\u003c/strong\\u003e) là phương pháp chiêm tinh bí truyền trứ danh của bậc tiền nhân \\u003cstrong\\u003eViên Thiên Cang\\u003c/strong\\u003e đời nhà Đường. Bằng cách quy đổi \\u003cstrong\\u003eNăm sinh\\u003c/strong\\u003e, \\u003cstrong\\u003eTháng sinh\\u003c/strong\\u003e, \\u003cstrong\\u003eNgày sinh\\u003c/strong\\u003e và \\u003cstrong\\u003eGiờ sinh Âm Lịch\\u003c/strong\\u003e thành đơn vị \\u003cem\\u003eLượng\\u003c/em\\u003e và \\u003cem\\u003eChỉ\\u003c/em\\u003e, hệ thống cộng tổng trọng lượng số mệnh để luận giải công danh, tiền tài, gia đạo, thăng trầm và hậu vận một kiếp người.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e1. Giới thiệu nguồn gốc thuật Cân Xương Tính Cốt\\u003c/h3\\u003e\\n      \\u003cp\\u003ePhương pháp \\u003cstrong\\u003eCân Xương Đoán Số\\u003c/strong\\u003e là một tuyệt kỹ chiêm tinh cổ truyền được tương truyền do bậc cao nhân Viên Thiên Cang biên soạn. Phương pháp này quy đổi Năm sinh, Tháng sinh, Ngày sinh và Giờ sinh âm lịch thành đơn vị \\u0027Lượng\\u0027 và \\u0027Chỉ\\u0027 để đúc kết số mệnh qua những bài phú thơ cổ truyền xác thực.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e2. Cách tính tổng số lượng chỉ bản mệnh\\u003c/h3\\u003e\\n      \\u003cp\\u003eCông thức cơ bản:\\u003c/p\\u003e\\n      \\u003cdiv style=\\\"background: #FFFDF8; border: 1.5px solid #DFBA73; padding: 14px 18px; border-radius: 6px; font-weight: 700; color: #7A1414; margin: 12px 0;\\\"\\u003e\\n        TỔNG SỐ LƯỢNG CHỈ = Lượng Năm + Lượng Tháng + Lượng Ngày + Lượng Giờ\\n      \\u003c/div\\u003e\\n      \\u003cp\\u003eTổng số lượng chỉ nhẹ nhất là \\u003cstrong\\u003e2 lượng 1 chỉ\\u003c/strong\\u003e, và nặng nhất đạt đến \\u003cstrong\\u003e7 lượng 1 chỉ\\u003c/strong\\u003e. Thông thường, số chỉ càng cao thì vận số tiền tài, phước lộc càng hanh thông sung túc.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e3. Ý nghĩa khái lược các thang lượng chỉ\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTừ 2 lượng 2 đến 3 lượng 5:\\u003c/strong\\u003e Tuổi trẻ gian nan vất vả, phải tự lực cánh sinh, lập nghiệp tha hương mới mong thành công. Về hậu vận sẽ dần ổn định ấm no.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTừ 3 lượng 6 đến 4 lượng 8:\\u003c/strong\\u003e Số phận thanh nhã, có tài nghệ và chữ tín. Công danh sự nghiệp phát triển vững vàng từ độ trung niên, gia đạo hòa thuận.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTừ 4 lượng 9 đến 6 lượng 0:\\u003c/strong\\u003e Số hưởng vinh hoa phú quý, sinh ra trong gia đình gia giáo hoặc có quý nhân kề cận nâng đỡ, tiền bạc dồi dào, thọ khang trường cửu.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTừ 6 lượng 1 đến 7 lượng 1:\\u003c/strong\\u003e Mệnh cách quý hiển tột bậc, đại phú đại quý, làm rạng danh dòng tộc và được muôn người kính trọng.\\u003c/p\\u003e\\n    \"},{\"id\":\"tuvi-12-con-giap-dau-nam\",\"tieuDe\":\"Xem Tử Vi Năm 2026: Luận Đoán Cát Hung 12 Con Giáp \\u0026 Vận Trình Đầu Xuân\",\"chuyenMuc\":\"Tử Vi 2026\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"26/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Tử Vi 2026.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Dự báo chi tiết vận trình công danh, tài lộc, gia đạo và sức khỏe của 12 con giáp trong năm mới. Khám phá các cơ hội phát triển và phương vị nghênh tiếp cát thần đại cát.\",\"noiDung\":\"\\n      \\u003cp style=\\\"font-size: 15.5px; line-height: 1.8; color: #2C241E; margin-bottom: 18px; text-align: justify;\\\"\\u003e\\n        \\u003cstrong\\u003eTử vi đầu năm 2026\\u003c/strong\\u003e là nội dung giúp bạn tham khảo những xu hướng và diễn biến nổi bật có thể xảy ra trong năm mới dựa trên \\u003cstrong\\u003enăm sinh\\u003c/strong\\u003e, \\u003cstrong\\u003egiới tính\\u003c/strong\\u003e và \\u003cstrong\\u003engũ hành bản mệnh\\u003c/strong\\u003e. Khác với việc xem tử vi hàng ngày hay tử vi trọn đời, tử vi đầu năm tập trung sâu vào trường khí của năm mới \\u003cstrong\\u003eBính Ngọ 2026\\u003c/strong\\u003e, từ đó đưa ra những thông tin tham khảo toàn diện về công việc, tài lộc, tình cảm, gia đạo, sức khỏe và các hoạt động nên thực hiện hoặc cần lưu ý. Khi xem tử vi đầu năm, hệ thống sẽ kết hợp nhiều yếu tố như \\u003cstrong\\u003eCan Chi năm sinh\\u003c/strong\\u003e, \\u003cstrong\\u003engũ hành bản mệnh\\u003c/strong\\u003e, \\u003cstrong\\u003esao chiếu mệnh Lưu Niên\\u003c/strong\\u003e, \\u003cstrong\\u003ehạn Tam Tai - Kim Lâu - Hoang Ốc\\u003c/strong\\u003e và \\u003cstrong\\u003evận hạn Thái Tuế\\u003c/strong\\u003e để luận giải chi tiết và đưa ra lời khuyên đón lành tránh dữ cho từng bản mệnh.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e1. Bức tranh vận trình 12 Con Giáp đầu xuân năm mới\\u003c/h3\\u003e\\n      \\u003cp\\u003eMỗi chu kỳ năm mới mở ra sự chuyển dịch của các chòm sao Lưu Niên như Thái Tuế, Tuế Phá, Lộc Tồn, Thiên Mã, Tang Môn, Bạch Hổ. Việc nắm bắt hung cát vận hạn ngay từ đầu xuân giúp quý bản mệnh chủ động nghênh đón cát khí, hạn chế rủi ro và phát huy tối đa tiềm năng bản thân.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e2. Đặc Điểm Tính Cách 12 Con Giáp\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Tý:\\u003c/strong\\u003e Nhanh nhẹn, thông minh và sắc sảo trong phán đoán. Họ luôn biết nắm bắt thời cơ để gặt hái thành công trong cuộc sống.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Sửu:\\u003c/strong\\u003e Siêng năng, kiên định và chịu thương chịu khó. Họ sở hữu ý chí vững vàng và tinh thần trách nhiệm cực kỳ cao.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Dần:\\u003c/strong\\u003e Mạnh mẽ, quả cảm và tràn đầy nhiệt huyết. Họ mang phong thái của người lãnh đạo, sẵn sàng đương đầu với mọi thử thách.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Mão:\\u003c/strong\\u003e Tinh tế, khôn ngoan và sống rất ôn hòa, khéo léo. Họ luôn cẩn trọng trong mọi việc và tạo được thiện cảm lớn với xung quanh.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Thìn:\\u003c/strong\\u003e Uy quyền, hào phóng và có tầm nhìn chiến lược lớn. Họ luôn tỏa ra nguồn năng lượng mạnh mẽ để chinh phục những đỉnh cao mới.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Tỵ:\\u003c/strong\\u003e Sáng suốt, điềm tĩnh và ẩn chứa trí tuệ uyên bác. Họ có trực giác nhạy bén và luôn giữ được thế chủ động trong mọi tình huống.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Ngọ:\\u003c/strong\\u003e Phóng khoáng, nhiệt tình và luôn yêu thích sự tự do. Họ sở hữu nguồn năng lượng dồi dào và sự xông xáo trong mọi hành trình.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Mùi:\\u003c/strong\\u003e Nhân hậu, hiền hòa và sống giàu tình cảm. Họ mang tâm hồn nghệ sĩ, sự nhẫn nại và là điểm tựa bình yên cho mọi người.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Thân:\\u003c/strong\\u003e Thông minh tột đỉnh, linh hoạt và ứng biến cực kỳ giỏi. Họ hài hước, dí dỏm và có tài ngoại giao xuất sắc.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Dậu:\\u003c/strong\\u003e Chăm chỉ, sắc sảo và có kỷ luật bản thân rất cao. Họ luôn chỉn chu trong mọi chi tiết và rất ngay thẳng, trượng nghĩa.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Tuất:\\u003c/strong\\u003e Trung thành, trượng nghĩa và đặt chữ tín lên hàng đầu. Họ sống chân thành và luôn sẵn sàng bảo vệ những người xung quanh.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Hợi:\\u003c/strong\\u003e Phúc hậu, bao dung và luôn biết tận hưởng cuộc sống an nhiên. Họ thường gặp nhiều may mắn, quý nhân phù trợ và sự viên mãn.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e3. Phân tích chi tiết 4 nhóm Tam Hợp \\u0026 Vận hội mới\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eNhóm Thân - Tý - Thìn (Tam Hợp Thủy Cục):\\u003c/strong\\u003e Có nhiều cơ hội mở rộng quan hệ hợp tác làm ăn, tài chính có bước chuyển biến tích cực, nên chủ động nắm bắt thời cơ từ quý 2 trở đi.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eNhóm Dần - Ngọ - Tuất (Tam Hợp Hỏa Cục):\\u003c/strong\\u003e Năng lượng dồi dào, sự nghiệp thăng hoa nhưng cần giữ tâm thế khiêm tốn, tránh bốc đồng trong các quyết định đầu tư mạo hiểm.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eNhóm Tỵ - Dậu - Sửu (Tam Hợp Kim Cục):\\u003c/strong\\u003e Tài lộc tích lũy vững vàng, công việc kinh doanh đi vào quỹ đạo ổn định, gia đạo đón nhận nhiều tin vui hỷ sự.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eNhóm Hợi - Mão - Mùi (Tam Hợp Mộc Cục):\\u003c/strong\\u003e Khởi sắc về đường nhân duyên và học hành, thi cử, quý nhân tương trợ giúp vượt qua thử thách một cách êm đẹp.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e4. Phương vị và giờ lành xuất hành nghênh Tài Thần, Hỷ Thần\\u003c/h3\\u003e\\n      \\u003cp\\u003eVào ngày đầu năm mới, việc lựa chọn hướng xuất hành thuận phong thủy đóng vai trò khai mở luồng sinh khí may mắn. Quý gia chủ nên tra cứu kỹ hướng đón Tài Thần và Hỷ Thần hợp với bản mệnh để cả năm vạn sự cát tường.\\u003c/p\\u003e\\n    \"},{\"id\":\"xong-dat-dau-nam-dai-cat\",\"tieuDe\":\"Xông Đất Đầu Năm 2026: Cẩm Nang Chọn Tuổi Xông Nhà, Mở Hàng Đại Cát\",\"chuyenMuc\":\"Xông Đất Đầu Năm 2026\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"26/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xông Đất Đầu Năm 2026.png\",\"noiBat\":true,\"uuTienFeed\":2,\"tomTat\":\"Nghệ thuật chọn tuổi xông đất, mở hàng đầu năm mới chuẩn phong thủy cát nhật. Bảng 5 tiêu chí vàng Tam Hợp, Lục Hợp, Ngũ Hành tương sinh và quy trình 3 bước tự xông đất cho gia chủ.\",\"noiDung\":\"\\n      \\u003cp style=\\\"font-size: 15.5px; line-height: 1.8; color: #2C241E; margin-bottom: 18px; text-align: justify;\\\"\\u003e\\n        \\u003cstrong\\u003eXông đất đầu năm 2026\\u003c/strong\\u003e (còn gọi là \\u003cem\\u003eđạp đất\\u003c/em\\u003e) là một nét đẹp văn hóa lâu đời của dân tộc Việt Nam vào thời khắc chuyển giao năm mới. Người xưa tin rằng người đầu tiên bước chân vào nhà sau giờ Giao thừa sẽ đem lại vận khí, may rủi và phúc lộc cho gia chủ trong suốt 365 ngày của năm đó. Dựa trên \\u003cstrong\\u003enăm sinh của gia chủ\\u003c/strong\\u003e và \\u003cstrong\\u003enăm xem\\u003c/strong\\u003e, hệ thống sẽ đối chiếu toàn diện về \\u003cstrong\\u003eThiên Can\\u003c/strong\\u003e, \\u003cstrong\\u003eĐịa Chi (Tam Hợp, Lục Hợp)\\u003c/strong\\u003e, \\u003cstrong\\u003eNgũ Hành tương sinh\\u003c/strong\\u003e và \\u003cstrong\\u003eVận Niên\\u003c/strong\\u003e để chọn ra những tuổi xông nhà, xông đất và mở hàng đại cát nhất, giúp kích hoạt tài lộc, bình an cho cả gia đình.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3 style=\\\"font-family: \\u0027Cinzel\\u0027, serif; color: var(--primary, #7A1414); font-size: 17px; font-weight: 800; margin-top: 22px; margin-bottom: 12px; border-left: 4px solid var(--gold, #DFBA73); padding-left: 10px;\\\"\\u003e\\n        1. Ý nghĩa \\u0026amp; Bí quyết chọn người Xông Đất đầu xuân\\n      \\u003c/h3\\u003e\\n      \\u003cp style=\\\"margin-bottom: 16px; text-align: justify;\\\"\\u003e\\n        Thời khắc sau Giao thừa là lúc đất trời giao hòa, âm dương chuyển dịch và trường khí trong ngôi nhà bắt đầu khởi tạo cho một chu kỳ vận hành mới. Người bước chân đầu tiên vào nhà sau giờ Giao thừa mang theo nguồn sinh khí quyết định đến sự hanh thông của gia đạo. Một người xông đất hợp tuổi, bản mệnh tương sinh, tính tình vui vẻ, hiền hòa và đang làm ăn phát đạt sẽ đem lại vượng khí dồi dào, xua tan điều xui rủi và mang tới cả năm an khang thịnh vượng.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3 style=\\\"font-family: \\u0027Cinzel\\u0027, serif; color: var(--primary, #7A1414); font-size: 17px; font-weight: 800; margin-top: 22px; margin-bottom: 12px; border-left: 4px solid var(--gold, #DFBA73); padding-left: 10px;\\\"\\u003e\\n        2. 5 Tiêu chí vàng chọn người Xông Đất, Mở Hàng đại cát\\n      \\u003c/h3\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eTương sinh về Ngũ Hành, Tam Hợp, Lục Hợp:\\u003c/strong\\u003e Bản mệnh và Thiên can, Địa chi của người xông đất tương sinh hỗ trợ cho gia chủ (Mộc sinh Hỏa, Hỏa sinh Thổ, Thổ sinh Kim, Kim sinh Thủy, Thủy sinh Mộc; thuộc các bộ Tam Hợp, Lục Hợp cát tường) và không bị xung khắc với Thái Tuế của năm.\\n      \\u003c/p\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eTránh Tứ Hành Xung \\u0026amp; Tương Hại:\\u003c/strong\\u003e Tuyệt đối không chọn người có tuổi chính xung (Tý - Ngọ, Mão - Dậu, Dần - Thân, Tỵ - Hợi, Thìn - Tuất, Sửu - Mùi) hoặc tương hại, tương phá với bản mệnh chủ nhà.\\n      \\u003c/p\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eVía Lành, Tính Tình Xởi Lởi:\\u003c/strong\\u003e Chọn người hoạt bát, vui vẻ, hiền hòa, sống có đức và luôn mang lại năng lượng tích cực cho mọi người xung quanh.\\n      \\u003c/p\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eCông Việc Làm Ăn Thuận Lợi:\\u003c/strong\\u003e Ưu tiên người đang trên đà phát đạt, tài chính hanh thông, công danh thăng tiến để \\\"nhả vía lộc\\\" cho nhà mình.\\n      \\u003c/p\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eGia Đình Thuận Hòa, Ấm Êm:\\u003c/strong\\u003e Vợ chồng con cái hòa thuận, hiếu thảo, gia đạo yên vui, không có mâu thuẫn lục đục.\\n      \\u003c/p\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eKhông Mang Bụi Tang \\u0026amp; Vướng Biến Cố:\\u003c/strong\\u003e Kiêng kỵ tuyệt đối người đang chịu tang sự, phụ nữ đang mang thai hoặc gia đình gặp biến cố trắc trở trong năm vừa qua.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3 style=\\\"font-family: \\u0027Cinzel\\u0027, serif; color: var(--primary, #7A1414); font-size: 17px; font-weight: 800; margin-top: 22px; margin-bottom: 12px; border-left: 4px solid var(--gold, #DFBA73); padding-left: 10px;\\\"\\u003e\\n        3. Cách Gia Chủ Tự Xông Đất Cho Mình Chuẩn Phong Thủy\\n      \\u003c/h3\\u003e\\n      \\u003cp style=\\\"margin-bottom: 12px; text-align: justify;\\\"\\u003e\\n        Nếu trong trường hợp gia chủ không tìm được người có tuổi và tính cách ưng ý để nhờ xông đất, gia chủ hoàn toàn có thể \\u003cstrong\\u003etự xông đất cho chính ngôi nhà của mình\\u003c/strong\\u003e:\\n      \\u003c/p\\u003e\\n      \\u003cdiv style=\\\"background: #FAF6EF; border: 1px solid #E5D5BA; border-radius: 8px; padding: 14px 18px; margin-bottom: 16px;\\\"\\u003e\\n        \\u003cp style=\\\"margin: 0 0 10px 0; line-height: 1.6;\\\"\\u003e\\n          \\u003cstrong\\u003e• Bước 1:\\u003c/strong\\u003e Trước giờ Giao thừa (khoảng 23h00 đêm 30 Tết), một thành viên hợp tuổi trong gia đình mặc trang phục chỉnh tề, bước ra khỏi nhà.\\n        \\u003c/p\\u003e\\n        \\u003cp style=\\\"margin: 0 0 10px 0; line-height: 1.6;\\\"\\u003e\\n          \\u003cstrong\\u003e• Bước 2:\\u003c/strong\\u003e Đi đến đình, đền, chùa gần nhà hoặc đi về hướng Hỷ Thần / Tài Thần của năm để cầu an, hái lộc đầu xuân.\\n        \\u003c/p\\u003e\\n        \\u003cp style=\\\"margin: 0; line-height: 1.6;\\\"\\u003e\\n          \\u003cstrong\\u003e• Bước 3:\\u003c/strong\\u003e Đúng thời khắc sau Giao thừa (từ 00h15 đến 01h00 mùng 1), người đó quay trở về nhà, mang theo cành lộc may mắn hoặc bao lì xì đỏ vào nhà, gửi những lời chúc tốt lành đến các thành viên trong gia đình.\\n        \\u003c/p\\u003e\\n      \\u003c/div\\u003e\\n    \"},{\"id\":\"bai-pha-quan-dan-than\",\"tieuDe\":\"Phá Quân độc tọa ở hai cung Dần hoặc Thân\",\"chuyenMuc\":\"Tử Vi Đẩu Số\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"14/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Sao Phá Quan Dần Thân.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Phá Quân độc tọa hai cung Dần hoặc Thân; đối cung là \\u0027Vũ Khúc, Thiên Tướng\\u0027; cung tam phương là Thất Sát độc tọa. Cung Dần hoặc Thân là thế hãm địa của Phá Quân nhưng lại ẩn chứa tiềm năng khai mở vô cùng mãnh liệt, phá tan trở ngại để kiến thiết đại nghiệp vinh quang...\",\"noiDung\":\"\\u003cp\\u003ePhá Quân độc tọa hai cung Dần hoặc Thân; đối cung là \\\"Vũ Khúc, Thiên Tướng\\\"; cung tam phương là Thất Sát độc tọa. Cung Dần hoặc Thân là thế hãm địa của Phá Quân, chủ về sự khai sáng anh dũng phi thường, kiến lập sự nghiệp lớn trong bão táp.\\u003c/p\\u003e\\n      \\n      \\n      \\u003ch3\\u003e1. Đặc tính bản mệnh khi Phá Quân cư Dần Thân\\u003c/h3\\u003e\\n      \\u003cp\\u003ePhá Quân thuộc Thủy, hóa khí là Hao, chủ về sự xung phong trận mạc, không ngại gian khó, dám nghĩ dám làm và phá vỡ các khuôn mẫu cũ kỹ. Người có Phá Quân thủ Mệnh tại Dần Thân thường có tính cách độc lập từ rất sớm, sớm rời xa quê hương bản quán để tự thân lập nghiệp.\\u003c/p\\u003e\\n      \\u003cp\\u003eCuộc đời người này phải trải qua ít nhất một lần thăng trầm biến cố lớn trước khi đạt được đỉnh cao của danh vọng và tiền tài. Họ có tố chất của nhà cải cách, nhà kinh doanh tiên phong hoặc người đứng đầu các dự án đột phá.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e2. Ảnh hưởng của các sao hội tụ\\u003c/h3\\u003e\\n      \\u003cp\\u003eĐối cung có Vũ Khúc và Thiên Tướng chiếu về, mang lại năng lực tài chính và óc tổ chức quản trị thực tế. Nếu hội hợp được các cát tinh như Tả Phù, Hữu Bật, Hóa Lộc, Hóa Quyền thì đương số biến hung thành cát, danh tiếng vang dội bốn phương.\\u003c/p\\u003e\\n      \\u003cp\\u003eTuy nhiên, nếu gặp phải Kình Dương, Đà La, Không Kiếp hãm địa thì cần đề phòng tổn thất tài sản, nên chọn các ngành nghề kỹ thuật cao, cơ khí chế tạo, phẫu thuật ngoại khoa hoặc quân đội để hóa giải sát khí.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e3. Lời khuyên định hướng sự nghiệp\\u003c/h3\\u003e\\n      \\u003cp\\u003eNgười mệnh Phá Quân Dần Thân không nên chọn những công việc văn phòng gò bó, an phận thủ thường. Môi trường càng nhiều thách thức, cạnh tranh khốc liệt thì tài năng của họ càng được phát huy rực rỡ. Hôn nhân nên kết hôn muộn để giữ gìn hòa khí gia đạo lâu bền.\\u003c/p\\u003e\"},{\"id\":\"post-ly-tinh-cua-sao-tu-vi-1639\",\"tieuDe\":\"LÝ TÍNH CỦA SAO TỬ VI\",\"chuyenMuc\":\"Tử Vi Đẩu Số\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"15/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Lý Tính Của Sao Tử Vi.jpeg\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Các chính tinh thuộc chòm Tử Vi sinh ra từ quẻ Càn, theo vị trí các hào từ cao xuống thấp mỗi hào một sao. Quẻ Càn ngoài 6 hào dương còn có một hào rất đặc biệt...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eCác chính tinh thuộc chòm Tử Vi sinh ra từ quẻ Càn, theo vị trí các hào từ cao xuống thấp mỗi hào một sao. Quẻ Càn ngoài 6 hào dương còn có một \\u0027hào\\u0027 rất đặc biệt, đó là hào 7, \\u0027Dụng cửu, Kiến quần long vô thủ\\u0027, đây chính là chỗ phát sinh ra sao Thiên Phủ. Quẻ Càn toàn hào dương, nhưng lại dùng hào 7 chính là do gặp phải cái âm động. Trong Dịch có một môn là Thái Ất, khi xem quẻ Ất, để tìm hào động ứng việc ta phải xem địa chi động số rồi đếm các hào trong quẻ. Chi dương thì đếm hào dương, chi âm thì đếm hào âm. Quẻ Càn thuần dương, nếu gặp địa chi âm thì do không có hào âm nào nên kết quả toàn bộ các hào dương đều tĩnh, khi đó, ta dùng \\u0027hào 7\\u0027 để xét việc.\\u003c/p\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eSao Tử Vi còn gọi là Đế tọa đứng đầu 12 vì sao trong lá số Tử Vi, thuộc tính ngũ hành là Âm Thổ, là trung tâm của các vì sao. Tử Vi chuyên quản về tước lộc, có tác dụng hóa giải tai ách, kéo dài tuổi thọ, chủ hóa (chủ phúc và hóa giải hung tính của các sát tinh).\\u003c/p\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eTử Vi thuộc Âm Thổ chủ tinh Bắc đẩu, hóa là Đế Quân, thường là chủ tinh ắt sẽ cần \\u0027Quần Thần Củng Chiếu\\u0027. Chính vì thế mà Tử Vi nhất định phải được Quần Thần củng chiếu mới là thượng cách, nếu không có quần thần khánh hội thì chỉ là cách cục bình thường. Quần thần ở đây nếu như hội hợp được chủ tinh thì có sự trợ giúp rất lớn như Thiên Phủ - Thiên Tướng ắt sẽ mạnh mẽ, có tài, có thế. Là tượng của Đế Hoàng nên cần sự trợ sức của Tả Phù - Hữu Bật đồng cung phò tá, lòng dạ cũng rộng rãi. Nếu có Xương Khúc làm tùy tùng cùng hội hợp, thì có học thức, có trí tài, cũng có khả năng làm giảm nhẹ cái tính cao ngạo, chủ quan của Tử Vi. Khôi Việt chủ truyền lệnh hội hợp thì có nhân gặp nhiều cơ hội, có khả năng gia tăng địa vị. Thái Dương, Thái Âm phân chức. Gặp Lộc Tồn có nghĩa tiền bạc chất đống trong kho đụn.\\u003c/p\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eNếu như Quần Thần xa lánh, trở thành Cô Quân chủ quan quá sâu, tâm cao khí ngạo mà mừng giận thất thường, không khéo đối xử với người. Nếu gặp Không Vong - Hoa Cái thường có tư tưởng độc tài. Nếu gia Tứ Sát là vua vô đạo thuộc hạ cách, nếu thêm Phúc cung không tốt thì là người hèn mọn dung tục.\\u003c/p\\u003e\"},{\"id\":\"tuong-so-not-ruoi\",\"tieuDe\":\"Kinh nghiệm người xưa xem nốt ruồi Cát - Hung trên khuôn mặt\",\"chuyenMuc\":\"Xem Tướng Nốt Ruồi\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"02/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tướng Nốt Ruồi.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Dân gian có câu: \\u0027Nốt ruồi ẩn tàng là quý, nốt ruồi lộ liễu là hung\\u0027. Khám phá bản đồ định vị nốt ruồi phú quý thọ yểu trên gương mặt theo tướng pháp cổ truyền...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eTheo quan niệm cổ nhân, nốt ruồi trên khuôn mặt ví như cây cỏ trên núi, đồi son đất đỏ sinh cỏ thơm, núi cằn sỏi đá sinh cỏ dại. Nốt ruồi đen lánh như mun hoặc đỏ rực như chu sa, ẩn tàng ở nơi kín đáo (chân mày, dái tai, ấn đường) là biểu hiện của tài lộc và phúc đức trời ban.\\u003c/p\\u003e\\n\\u003ch3\\u003e1. Nốt ruồi cung Tài Bạch (Đầu mũi \\u0026 Cánh mũi)\\u003c/h3\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eMũi cai quản cung Tài Bạch. Đầu mũi có nốt ruồi son chủ về nguồn thu bất ngờ, tiền bạc hanh thông. Tuy nhiên nếu là nốt ruồi đen sạm nằm lộ thiên ngay chuẩn đầu hoặc cánh mũi thì cần cẩn trọng quản lý tài chính, tránh tiêu xài hoang phí.\\u003c/p\\u003e\\n\\u003ch3\\u003e2. Nốt ruồi trong lông mày (Thảo lý tàng châu)\\u003c/h3\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eNốt ruồi ẩn trong lông mày gọi là \\u0027Ngọc ẩn trong cỏ\\u0027. Đây là quý tướng bậc nhất, chủ về người túc trí đa mưu, có quý nhân phù trợ lúc nguy nan và hậu vận con cháu hiển đạt vinh hoa.\\u003c/p\\u003e\"},{\"id\":\"tuong-so-ngu-quan\",\"tieuDe\":\"Tướng Pháp Cổ Truyền \\u0026 Ngũ Quan: Luận Khí Sắc \\u0026 Thần Khí Khuôn Mặt Đoán Vận Mệnh\",\"chuyenMuc\":\"Diện Tướng\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"01/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Ngũ Quan Luận Tướng.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Kinh nghiệm cổ nhân xem Ngũ Quan định phú quý thọ yểu: \\u0027Vấn phú tại tỵ, vấn quý tại nhãn, vấn phúc tại khẩu, vấn thọ tại nhĩ, vấn danh tại mi\\u0027...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eNăm cơ quan Mắt, Mũi, Miệng, Tai, Lông mày phản chiếu trọn vẹn khí chất và vận mệnh đời người. Quan sát Ngũ Quan phối hợp thần sắc giúp ta thấu suốt tâm can, đoán định thời vận cát hung.\\u003c/p\\u003e\\n\\u003ch3\\u003e1. Mắt (Giám Sát Quan)\\u003c/h3\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eMắt là cửa sổ tâm hồn, phản chiếu thần khí. Mắt sáng, tròng đen tròng trắng phân minh, ánh mắt nhìn thẳng từ tốn uy nghiêm là tướng đại quý nhân.\\u003c/p\\u003e\\n\\u003ch3\\u003e2. Mũi (Thẩm Biện Quan)\\u003c/h3\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eSống mũi thẳng tắp, không gồ ghề lộ xương, đầu mũi tròn trịa nở nang là kho vàng tích trữ của cải vững bền suốt đời.\\u003c/p\\u003e\"},{\"id\":\"tuong-so-tam-dinh\",\"tieuDe\":\"Tam Đình Bình Đẳng: Luận Tiền Vận, Trung Vận \\u0026 Hậu Vận Khuôn Mặt\",\"chuyenMuc\":\"Tướng Mạo \\u0026 Tam Đình\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"30/08/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Tam Đình.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Người xưa chia khuôn mặt thành 3 phần: Thượng Đình (15-30 tuổi), Trung Đình (31-50 tuổi) và Hạ Đình (sau 50 tuổi) để đoán định vận trình tam thế...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eCổ nhân có câu: \\u0027Tam đình bình đẳng, nhất sinh y thực vô ưu\\u0027. Khuôn mặt có Tam Đình cân xứng, phân bố hài hòa, khí sắc sáng nhuận là biểu hiện của cuộc đời an định, gia đạo thuận hòa.\\u003c/p\\u003e\"},{\"id\":\"tuong-so-chi-tay\",\"tieuDe\":\"Bí Truyền Thuật Xem Chỉ Tay: Luận Đoán 3 Đường Sinh Đạo, Trí Đạo \\u0026 Tâm Đạo\",\"chuyenMuc\":\"Xem Tướng Chỉ Tay\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"28/08/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tướng Chỉ Tay.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Giải mã bí ẩn các đường chỉ tay chính và các gò bàn tay. Phương pháp nhận biết đường quý nhân, đường định mệnh và dấu hiệu tiền bạc dồi dào...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eLòng bàn tay như mảnh đất trời ban, các đường chỉ tay tựa như sông ngòi khai thông sinh khí. Đường Sinh Đạo sâu dài, Trí Đạo rõ nét, Tâm Đạo ngay ngắn là tướng người trí tuệ hanh thông, trường thọ đại phúc.\\u003c/p\\u003e\"},{\"id\":\"tuong-so-ca-dao\",\"tieuDe\":\"Ca Dao Tục Ngữ Người Xưa Xem Tướng: Đúc Kết Trí Tuệ Dân Gian\",\"chuyenMuc\":\"Ca Dao Tục Ngữ Xem Tướng\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"25/08/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Ca Dao Tục Ngữ Xem Tướng.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Tổng hợp các câu ca dao tục ngữ kinh điển về nhân tướng học: \\u0027Những người béo trục béo tròn\\u0027, \\u0027Đàn ông miệng rộng thì sang\\u0027 và bài học ứng xử cuộc đời...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eTrí tuệ dân gian ngàn đời đã đúc kết thuật xem tướng qua những vần thơ, câu ca dao mộc mạc mà vô cùng sâu sắc, giúp nhận diện tính cách và phẩm hạnh con người.\\u003c/p\\u003e\"},{\"id\":\"tuong-so-tai-duc\",\"tieuDe\":\"Tướng Tự Tâm Sinh: Tâm Đức Cải Biến Tướng Mạo \\u0026 Số Mệnh\",\"chuyenMuc\":\"Khí Sắc \\u0026 Thần Khí\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"20/08/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Tướng Khí Qua Cử Chỉ Âm Thanh.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Cổ nhân dạy: \\u0027Hữu tâm vô tướng, tướng tự tâm sinh; Hữu tướng vô tâm, tướng tùy tâm diệt\\u0027. Sức mạnh của sự tu dưỡng cải biến vận mệnh...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eHình tướng bên ngoài chỉ là tấm gương phản chiếu tâm thức bên trong. Nuôi dưỡng lòng từ bi, hành thiện tích đức chính là phương thuốc tối thượng chuyển hung hóa cát, làm cho diện mạo ngày càng phúc hậu sáng ngời.\\u003c/p\\u003e\"}]",
    "KIENTHUC_BAI_VIET_CUSTOM":  "[{\"id\":\"bai-kinh-dich-que-can\",\"tieuDe\":\"Kinh Dịch Ứng Dụng: Ý Nghĩa Quẻ Càn Vi Thiên Trong Dự Đoán Sự Nghiệp\",\"chuyenMuc\":\"Kinh Dịch Chiêm Bốc\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"05/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Quẻ Càn Trong Kinh Dịch.png\",\"noiBat\":false,\"uuTienFeed\":1,\"tomTat\":\"Quẻ Thuần Càn: Sức mạnh cương kiện của rồng thiêng qua 6 hào. Từ \\u0027Tiềm long vật dụng\\u0027 đến \\u0027Phi long tại thiên\\u0027 - bài học ứng xử trong từng giai đoạn lập thân kiến quốc...\",\"noiDung\":\"\\u003cp\\u003eQuẻ Càn (Càn Vi Thiên) là quẻ đầu tiên trong 64 quẻ Kinh Dịch, đại diện cho Trời, cho đấng trượng phu, sự cương trực, sáng suốt và năng lượng vận động không ngừng nghỉ.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"tuvi-can-xuong-tinh-cot\",\"tieuDe\":\"Cân Xương Đoán Số: Bảng Tra Cân Xương Tính Cốt \\u0026 Giải Mã Lượng Chỉ Cuộc Đời\",\"chuyenMuc\":\"Các Thuật Số Khác\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"02/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Cân Xương Đoán Số.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Phương pháp Cân Xương Tính Cốt trứ danh của Lão Tử và Viên Thiên Cang. Hướng dẫn tính tổng lượng chỉ Năm - Tháng - Ngày - Giờ sinh và tra cứu bài thơ định mệnh chuẩn xác.\",\"noiDung\":\"\\u003cp\\u003ePhương pháp Cân Xương Đoán Số quy đổi Năm sinh, Tháng sinh, Ngày sinh và Giờ sinh âm lịch thành đơn vị Lượng và Chỉ để đúc kết số mệnh qua những bài phú thơ cổ truyền xác thực.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"boisim-phong-thuy-cat-hung\",\"tieuDe\":\"Bói Sim Phong Thủy: Luận Cát Hung Số Điện Thoại Theo Bát Quái \\u0026 Ngũ Hành\",\"chuyenMuc\":\"Xem Bói Sim\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"01/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Luận Giải Phong Thủy Sim Số.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Hướng dẫn tra cứu quẻ dịch sim số điện thoại, ngũ hành tương phối và số nút cát tường giúp gia tăng tài vận, kích hoạt may mắn.\",\"noiDung\":\"\\u003cp\\u003eSim phong thủy là trường năng lượng số gắn liền với cuộc sống hàng ngày. Luận sim theo Kinh Dịch và Ngũ Hành giúp đương số chọn dãy số tương sinh bản mệnh.\\u003c/p\\u003e\",\"updatedAt\":1792020983905}]",
    "XEMNGAY_BAI_VIET_CUSTOM":  "[{\"id\":\"xem-ngay-tot-tong-quan\",\"tieuDe\":\"Bí Quyết Chọn Ngày Lành Tháng Tốt: Nghênh Cát Tránh Hung Theo Đổng Công Tuyển Trạch\",\"chuyenMuc\":\"XEM NGÀY TỐT\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"15/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Tốt.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Hướng dẫn tổng quan về thuật trạch nhật cổ truyền, phương pháp phối hợp Thiên Can, Địa Chi, Ngũ Hành, Nhị Thập Bát Tú và hệ thống Thần Sát để lựa chọn ngày đại cát khởi sự bình an.\",\"noiDung\":\"\\u003ch3\\u003e1. Ý nghĩa sâu sắc của việc chọn ngày lành tháng tốt\\u003c/h3\\u003e\\n      \\u003cp\\u003eCổ nhân có câu: \\u003cem\\u003e\\\"Thiên thời - Địa lợi - Nhân hòa\\\"\\u003c/em\\u003e. Trong ba yếu tố kiến tạo nên sự thành bại viên mãn của đời người, Thiên thời chính là yếu tố đứng đầu. Thuật Trạch Nhật (chọn ngày tốt) ra đời từ hàng ngàn năm trước nhằm giúp con người hòa nhịp với trường năng lượng của vũ trụ, tránh những thời điểm trường khí xung sát, từ đó nghênh đón phúc lộc và vạn sự hanh thông.\\u003c/p\\u003e\\n      \\n      \\u003ch3\\u003e2. Các nguyên tắc cốt lõi khi trạch nhật\\u003c/h3\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Loại bỏ ngày đại kỵ:\\u003c/strong\\u003e Tuyệt đối tránh các ngày Sát Chủ, Thụ Tử, Tam Nương (mùng 3, 7, 13, 18, 22, 27 âm lịch), Nguyệt Kỵ (mùng 5, 14, 23 âm lịch) và ngày Dương Công Kỵ Nhật.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Chọn ngày Hoàng Đạo \\u0026 Trực Cát:\\u003c/strong\\u003e Ưu tiên 6 ngày Hoàng Đạo (Thanh Long, Minh Đường, Kim Quỹ, Thiên Đức, Ngọc Đường, Tư Mệnh) kết hợp Trực Khai, Kiến, Trừ, Định.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Hài hòa Bản Mệnh:\\u003c/strong\\u003e Can Chi của ngày phải tương sinh hoặc tương hỗ với bản mệnh gia chủ, tránh tương xung tương hình (ví dụ người tuổi Tý tránh chọn ngày Ngọ).\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"xem-ngay-mua-xe-cat-loi\",\"tieuDe\":\"Xem Ngày Mua Xe Hợp Tuổi: Chọn Ngày Cát Tinh Nghênh Tài Khí, Vạn Dặm Bình An\",\"chuyenMuc\":\"Xem ngày mua xe\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"15/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Ngày Tốt Mua Xe.png\",\"noiBat\":true,\"uuTienFeed\":2,\"tomTat\":\"Chi tiết các tiêu chí phong thủy khi trạch nhật mua xe ô tô, xe máy: Chọn ngày Đại An, Tốc Hỷ, sao Lộc Tồn để phương tiện luôn mang lại may mắn, tài lộc cho chủ nhân.\",\"noiDung\":\"\\u003ch3\\u003e1. Tầm quan trọng của ngày mua xe trong phong thủy\\u003c/h3\\u003e\\n      \\u003cp\\u003ePhương tiện đi lại gắn liền với sự an toàn tính mạng và công danh tài vận của mỗi người. Mua xe vào ngày cát lợi không những giúp tâm lý gia chủ vững vàng, tay lái bình an mà còn kích hoạt vượng khí, thuận đường làm ăn buôn bán.\\u003c/p\\u003e\\n      \\n      \\u003ch3\\u003e2. Cách chọn ngày giờ mua xe chuẩn xác\\u003c/h3\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Chọn ngày có cát tinh:\\u003c/strong\\u003e Ưu tiên các ngày có sao Thiên Mã, Lộc Mã, Phúc Sinh, Thiên Đức hợp chiếu. Tránh ngày có sao Kiếp Sát, Thiên Tặc, Nguyệt Phá.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Chọn khung giờ Hoàng Đạo:\\u003c/strong\\u003e Khi nhận xe và lăn bánh rời showroom, cần xuất phát đúng vào giờ cát (như giờ Đại An, Tốc Hỷ) và hướng đầu xe về phía phương cát lợi (Hỷ Thần, Tài Thần).\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"xem-ngay-xuat-hanh-hanh-thong\",\"tieuDe\":\"Xem Ngày Xuất Hành: Định Hướng Hỷ Thần, Tài Thần Để Đi Đến Nơi Về Đến Chốn\",\"chuyenMuc\":\"Xem ngày xuất hành\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"14/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Xuất Hành.png\",\"noiBat\":true,\"uuTienFeed\":3,\"tomTat\":\"Bảng tra cứu phương vị xuất hành nghênh tiếp Hỷ Thần, Tài Thần; bí quyết tránh Hạc Thần và giờ Không Vong theo Khổng Minh Lục Nhâm khi đi xa, công tác, du xuân.\",\"noiDung\":\"\\u003ch3\\u003e1. Phương pháp định hướng xuất hành\\u003c/h3\\u003e\\n      \\u003cp\\u003eKhi bước chân ra khỏi ngõ đầu tiên trong chuyến đi, việc chọn đúng hướng nghênh Thần mang ý nghĩa quyết định cát hung của chuyến hành trình:\\u003c/p\\u003e\\n      \\n      \\u003cul\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eHỷ Thần:\\u003c/strong\\u003e Chủ về tin vui, hỷ sự, tình duyên thắm nồng, gặp gỡ thuận lợi.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eTài Thần:\\u003c/strong\\u003e Chủ về đàm phán hợp đồng, kinh doanh thu lợi nhuận cao.\\u003c/li\\u003e\\n        \\u003cli\\u003e\\u003cstrong\\u003eHạc Thần:\\u003c/strong\\u003e Chủ về khẩu thiệt, thị phi - Cần tuyệt đối tránh hướng đối diện Hạc Thần.\\u003c/li\\u003e\\n      \\u003c/ul\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"xem-ngay-tot-ket-hon-tram-nam\",\"tieuDe\":\"Xem Ngày Tốt Kết Hôn: Trạch Nhật Đính Hôn - Thành Hôn Cho Tình Duyên Bền Chặt\",\"chuyenMuc\":\"Xem ngày tốt kết hôn\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"14/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Tốt Kết Hôn.png\",\"noiBat\":true,\"uuTienFeed\":4,\"tomTat\":\"Quy trình xem ngày cưới hỏi chuẩn cổ truyền: Lấy tuổi cô dâu làm gốc tính Kim Lâu, chọn ngày Hoàng Đạo, trực Thành, trực Mãn, loại trừ ngày Cô Quả, Quả Tú.\",\"noiDung\":\"\\u003ch3\\u003e1. Nguyên tắc \\u0027Lấy vợ xem tuổi đàn bà\\u0027\\u003c/h3\\u003e\\n      \\u003cp\\u003eTrong đại sự hôn nhân, tuổi cô dâu là căn cứ cốt lõi để tính năm không phạm Kim Lâu. Sau khi chọn được năm tốt, việc chọn tháng đại lợi (Tháng Bất Tương) và ngày Hoàng Đạo sẽ giúp vợ chồng hòa thuận, con cái đề huề, bách niên giai lão.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"xem-ngay-hoang-dao-6-sao\",\"tieuDe\":\"Xem Ngày Hoàng Đạo: Ý Nghĩa \\u0026 Cách Ứng Dụng 6 Hoàng Đạo Tinh Trong Đời Sống\",\"chuyenMuc\":\"Xem ngày hoàng đạo\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"13/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Hoàng Đạo.png\",\"noiBat\":true,\"uuTienFeed\":5,\"tomTat\":\"Tìm hiểu chi tiết về 6 sao Hoàng Đạo (Thanh Long, Minh Đường, Kim Quỹ, Thiên Đức, Ngọc Đường, Tư Mệnh) và cách phối hợp trực nhật để chọn thời điểm cát lành nhất...\",\"noiDung\":\"\\u003ch3\\u003e1. Ý nghĩa 6 sao Hoàng Đạo\\u003c/h3\\u003e\\n      \\n      \\u003cp\\u003e\\u003cstrong\\u003e• Thanh Long:\\u003c/strong\\u003e Đại cát, mọi việc cầu tài lộc công danh đều hanh thông.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Minh Đường:\\u003c/strong\\u003e Lợi cho việc học tập, kết giao quý nhân, thi cử thăng tiến.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Kim Quỹ:\\u003c/strong\\u003e Sao chủ về kho tàng, tài sản, rất tốt cho khai trương, ký hợp đồng, mua điền sản.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Thiên Đức:\\u003c/strong\\u003e Vạn phúc quy tông, hóa giải hung sát.\\u003c/p\\u003e\",\"updatedAt\":1790544014000},{\"id\":\"xem-ngay-dong-tho-khoi-cong\",\"tieuDe\":\"Xem Ngày Động Thổ: Định Ngày Khởi Công Công Trình An Lành, Tránh Tam Sát - Thái Tuế\",\"chuyenMuc\":\"Xem ngày động thổ\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"13/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Động Thổ.png\",\"noiBat\":true,\"uuTienFeed\":6,\"tomTat\":\"Khai móng, động thổ là nghi lễ giao cảm với Thổ Thần địa phương. Hướng dẫn chọn ngày vượng khí, tránh phương tọa phạm Tam Sát, Thái Tuế và Ngũ Hoàng...\",\"noiDung\":\"\\u003ch3\\u003e1. Tôn nghiêm nghi thức động thổ\\u003c/h3\\u003e\\n      \\u003cp\\u003eĐộng thổ tác động trực tiếp vào long mạch và nguyên khí khu đất. Ngày khởi công phải đảm bảo ngũ hành ngày tương sinh với hướng đất và bản mệnh gia chủ.\\u003c/p\\u003e\",\"updatedAt\":1790544156000},{\"id\":\"xem-ngay-tot-xay-dung\",\"tieuDe\":\"Xem Ngày Tốt Xây Dựng: Cẩm Nang Phong Thủy Kiến Tạo Gia Cư Vững Chắc\",\"chuyenMuc\":\"Xem ngày tốt xây dựng\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"12/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Tốt Xấy Dựng.png\",\"noiBat\":true,\"uuTienFeed\":7,\"tomTat\":\"Tổng hợp các bước trạch nhật trong toàn bộ quy trình xây dựng: từ đào móng, đổ trụ, xây tường đến hoàn thiện công trình...\",\"noiDung\":\"\\u003cp\\u003eXây nhà là việc trọng đại một đời người. Việc chọn đúng thời điểm khí trường thiên địa dung hòa giúp công nhân thi công thuận lợi, an toàn, ngôi nhà hoàn thành đón trọn sinh khí.\\u003c/p\\u003e\",\"updatedAt\":1790544208000},{\"id\":\"xem-ngay-do-tran-lop-mai\",\"tieuDe\":\"Xem Ngày Đổ Trần, Lợp Mái: Trạch Nhật Thượng Lương Cát Tinh Chiếu Mệnh\",\"chuyenMuc\":\"Xem ngày đổ trần, lợp mái\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"12/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Đổ Trần Lợp Mái.png\",\"noiBat\":true,\"uuTienFeed\":8,\"tomTat\":\"Thời khắc cất nóc, đổ mái đóng vai trò che chở gia đạo. Chọn ngày có sao Thiên Đức, Nguyệt Đức, Trực Định hoặc Trực Khai để nóc nhà vững chãi, ấm êm.\",\"noiDung\":\"\\u003cp\\u003eLễ cất nóc (Thượng Lương) phong tỏa trường khí của ngôi nhà, quyết định sự che chở và an khang của toàn bộ thành viên trong gia đình.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"xem-ngay-nhap-trach-nha-moi\",\"tieuDe\":\"Xem Ngày Nhập Trạch Nhà Mới: Lễ Nghi Dọn Về Nhà Mới Kích Hoạt Vượng Khí Gia Đạo\",\"chuyenMuc\":\"Xem ngày nhập trạch nhà mới\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"11/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Nhập Trạch.png\",\"noiBat\":true,\"uuTienFeed\":9,\"tomTat\":\"Nghi lễ nhập trạch dọn về nhà mới: Cách chọn ngày Thủy vượng (tinh tài), tránh ngày Hỏa vượng; trình tự mang bếp lửa, gạo nước vào nhà mới nghênh tài đón lộc...\",\"noiDung\":\"\\u003ch3\\u003e1. Nguyên tắc ngũ hành nhập trạch\\u003c/h3\\u003e\\n      \\u003cp\\u003eNhập trạch nên chọn ngày hành Thủy hoặc Kim để mang tiền tài, thanh tịnh vào nhà. Tránh ngày Hỏa khí quá vượng dễ sinh hỏa hoạn, nóng giận.\\u003c/p\\u003e\",\"updatedAt\":1790544321000},{\"id\":\"xem-ngay-mua-nha-giao-dich\",\"tieuDe\":\"Xem Ngày Mua Nhà: Chọn Ngày Ký Công Chứng, Giao Dịch Điền Sản Đắc Tài Đắc Lộc\",\"chuyenMuc\":\"Xem ngày mua nhà\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"11/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Mua Nhà.png\",\"noiBat\":true,\"uuTienFeed\":10,\"tomTat\":\"Bí quyết chọn ngày ký hợp đồng đặt cọc, công chứng mua đất mua nhà: Tránh ngày Không Vong, Phá Nhật để giao dịch thuận buồn xuôi gió, sinh lời bền vững.\",\"noiDung\":\"\\u003cp\\u003eMua nhà là đầu tư tài sản lớn. Chọn ngày có sao Lộc Tồn, Thiên Tài, Trực Thành sẽ giúp quá trình pháp lý minh bạch, điền sản vượng phát.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"xem-ngay-khai-truong-hong-phat\",\"tieuDe\":\"Xem Ngày Khai Trương: Chọn Giờ Hoàng Đạo Khai Mở Kinh Doanh Hồng Phát\",\"chuyenMuc\":\"Xem ngày khai trương\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"10/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Khai Trương.jpeg\",\"noiBat\":true,\"uuTienFeed\":11,\"tomTat\":\"Ngày mở hàng khai trương quyết định vận may và tài khí cả năm. Hướng dẫn chọn ngày Tam Hợp, Lục Hợp với tuổi chủ tiệm, nghênh tiếp khách quý tấp nập.\",\"noiDung\":\"\\u003ch3\\u003e1. \\u0027Đầu xuôi đuôi lọt\\u0027 trong kinh doanh\\u003c/h3\\u003e\\n      \\u003cp\\u003eLễ khai trương mở hàng kích hoạt trường khí năng động của cơ sở kinh doanh. Cần kết hợp cúng cáo Thần Tài Thổ Địa đúng khung giờ vàng.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"xem-ngay-ky-hop-dong-thanh-cong\",\"tieuDe\":\"Xem Ngày Ký Hợp Đồng: Tránh Ngày Nguyệt Kỵ, Đón Cát Tinh Đàm Phán Thắng Lợi\",\"chuyenMuc\":\"Xem ngày ký hợp đồng\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"10/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Ký Hợp Đồng.jpeg\",\"noiBat\":true,\"uuTienFeed\":12,\"tomTat\":\"Những điều tối kỵ khi chọn ngày ký kết thương mại, mua bán, hợp tác kinh doanh. Kinh nghiệm trạch cát để hợp đồng mang lại giá trị bền vững đôi bên.\",\"noiDung\":\"\\u003cp\\u003eKý hợp đồng cần sự sáng suốt của lý trí và trường khí bình ổn. Tránh tuyệt đối các ngày Sát Chủ, Thiên Lại, Hỏa Tinh.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"xem-ngay-tot-nhan-chuc-thang-tien\",\"tieuDe\":\"Xem Ngày Tốt Nhận Chức: Chọn Ngày Vượng Quan Lộc, Thanh Long Nghênh Vận Thăng Tiến\",\"chuyenMuc\":\"Xem ngày tốt nhận chức\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"09/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Tốt Nhận Chức.png\",\"noiBat\":true,\"uuTienFeed\":13,\"tomTat\":\"Xem ngày tiếp nhận vị trí công tác mới, nhận bằng khen, phong hàm: Kích hoạt cung Quan Lộc, quý nhân phò trợ, cấp dưới đồng lòng, sự nghiệp thăng hoa.\",\"noiDung\":\"\\u003cp\\u003eNgày đầu tiên ngồi vào ghế lãnh đạo mới mang dấu ấn năng lượng quyết định uy quyền và sự hanh thông trong nhiệm kỳ công tác.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"xem-ngay-an-tang-dao-hieu\",\"tieuDe\":\"Cải Táng Theo Quan Niệm Dân Gian\",\"chuyenMuc\":\"XEM NGÀY TỐT\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"16/10/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Ngày Tốt An Táng.jpeg\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Cải táng, còn được gọi là bốc mộ hoặc sang cát, là một phong tục mai táng truyền thống đã tồn tại lâu đời trong văn hóa của người Việt, thể hiện đạo hiếu và sự tôn kính tổ tiên.\",\"noiDung\":\"\\u003ch3\\u003e1. Ý nghĩa của phong tục cải táng\\u003c/h3\\u003e\\n      \\u003cp\\u003eCải táng, còn được gọi là bốc mộ hoặc sang cát, là một phong tục mai táng truyền thống đã tồn tại lâu đời trong văn hóa của người Việt. Đây không chỉ là việc quy tập hài cốt người thân về nơi an nghỉ vĩnh hằng mà còn là dịp để con cháu bày tỏ lòng hiếu kính, tri ân cội nguồn tổ tiên.\\u003c/p\\u003e\\n      \\u003ch3\\u003e2. Thời điểm và trạch nhật cải táng\\u003c/h3\\u003e\\n      \\u003cp\\u003eThời điểm cải táng thường được tiến hành vào những tháng cuối năm (từ tháng 9 đến tháng Chạp Âm lịch), khi thời tiết hanh khô, mát mẻ. Việc chọn ngày giờ bốc mộ cần hết sức cẩn trọng, tránh những ngày giờ phạm Trùng Tang, Tam Tang, Thụ Tử hoặc xung khắc với tuổi của người mất và trưởng nam.\\u003c/p\\u003e\",\"updatedAt\":1795200000000}]",
    "PHONGTHUY_BAI_VIET_CUSTOM":  "[{\"id\":\"bai-phong-thuy-nha-o\",\"tieuDe\":\"Phong Thủy Nhà Ở: Bát Trạch \\u0026 Cách Hóa Giải Hướng Nhà Xấu\",\"chuyenMuc\":\"Phong Thủy Nhà Ở\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"08/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Phong Thủy Bát Trạch.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Hướng dẫn nhận biết các phương vị hung hiểm Tuyệt Mệnh, Họa Hại, Lục Sát, Ngũ Quỷ trong phong thủy Bát Trạch...\",\"noiDung\":\"\\u003cp\\u003eTrong thuật phong thủy Bát Trạch Tam Nguyên Cửu Vận, hướng nhà đóng vai trò quyết định đến sinh khí, tài vận và sức khỏe của gia đình.\\u003c/p\\u003e\",\"updatedAt\":1792020983905},{\"id\":\"post-canh-quan-san-vuon-phong-thuy-nghe-thuat-muorl1zw\",\"tieuDe\":\"Cảnh Quan Sân Vườn Phong Thủy: Nghệ Thuật Tụ Khí \\u0026 Dẫn Thủy Khơi Thông Tài Lộc\",\"chuyenMuc\":\"Phong Thủy Đất đai\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"12/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Cảnh Quan Sân Vườn.jpg\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Hướng dẫn thiết kế tiểu cảnh, hồ cá koi, hòn non bộ chuẩn nguyên tắc Tọa sơn hướng thủy...\",\"noiDung\":\"\\u003cp\\u003eSân vườn phong thủy là khoảng không gian giao hòa giữa thiên nhiên và kiến trúc, mang nguồn sinh khí dồi dào cho toàn bộ ngôi gia.\\u003c/p\\u003e\",\"updatedAt\":1792020983905}]",
    "TUVI_BAI_VIET_CUSTOM":  "[{\"timestamp\":1792143478469,\"timeFormatted\":\"16/10/2026 - 16:37:58\",\"id\":\"tuvi-post-ban-ve-sao-khong-kiep-mvary3y7\",\"tieuDe\":\"Bàn Về Sao Không Kiếp\",\"chuyenMuc\":\"Tử Vi Đẩu Số\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"16/10/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Sao Địa Không - Địa Kiếp.jpeg\",\"tomTat\":\"Trong Tử Vi Đẩu Số, Không Kiếp là cách gọi chung của hai sát tinh Địa Không và Địa Kiếp. Đây là hai ngôi sao mang tính chất biến động mạnh, thường gắn với sự phá cách, thăng trầm, ...\",\"noiDung\":\"\\u003ch2 data-pm-slice=\\\"1 3 []\\\" style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e1. Khái quát về sao Không Kiếp\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eTrong Tử Vi Đẩu Số, Không Kiếp là cách gọi chung của hai sát tinh \\u003cstrong\\u003eĐịa Không và Địa Kiếp\\u003c/strong\\u003e. Đây là hai ngôi sao mang tính chất biến động mạnh, thường gắn với sự phá cách, thăng trầm, bất ngờ và những bước ngoặt lớn trong cuộc đời con người.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eĐịa Không và Địa Kiếp thuộc nhóm sao có tính chất đặc biệt, không hoàn toàn giống những sát tinh chủ về hình thương hay tranh chấp. Bộ sao này thường biểu hiện sự thay đổi đột ngột trong tư duy, hoàn cảnh sống, công danh, tài lộc và các mối quan hệ. Khi hội hợp với những cát tinh, người có Không Kiếp có thể bộc lộ năng lực khác thường, tư duy vượt khuôn khổ và khả năng tạo dựng thành tựu từ những hoàn cảnh khó khăn. Ngược lại, khi gặp nhiều hung sát tinh hoặc rơi vào vị trí bất lợi, chúng có thể làm gia tăng sự bất ổn, tổn thất và những biến cố khó lường.\\u003c/p\\u003e\\u003ch2 style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e2. Ý nghĩa sao Địa Không\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eĐịa Không thường được luận theo tính chất hư không, phá cách, tư tưởng khác biệt và khả năng nhìn ra những điều nằm ngoài khuôn mẫu thông thường. Người có Địa Không thủ Mệnh hoặc hội chiếu có thể có tư duy nhanh nhạy, thích tìm tòi, không dễ chấp nhận những quan niệm cứng nhắc.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eTuy nhiên, mặt trái của Địa Không là tính thiếu ổn định, dễ thay đổi mục tiêu hoặc có lúc suy tính nhiều nhưng kết quả không như mong muốn. Trong công việc và tài chính, sao này thường được xem là dấu hiệu cần chú ý đến những quyết định bất ngờ, kế hoạch thiếu chắc chắn và nguy cơ mất mát khi quá chủ quan.\\u003c/p\\u003e\\u003ch2 style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e3. Ý nghĩa sao Địa Kiếp\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eĐịa Kiếp mang sắc thái biến động, đột phá và những sự việc xảy ra ngoài dự liệu. Trong cách luận truyền thống, sao này thường được liên hệ với sự hao tổn, trở ngại, rủi ro hoặc những bước ngoặt buộc con người phải thay đổi hướng đi.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eỞ mặt tích cực, Địa Kiếp cũng có thể biểu hiện tinh thần quyết liệt, khả năng hành động trong hoàn cảnh khó khăn và xu hướng dám làm những việc người khác ngần ngại. Khi được các sao tốt hỗ trợ, người có Địa Kiếp có thể chuyển hóa trải nghiệm bất lợi thành kinh nghiệm, từ đó trưởng thành và có bản lĩnh hơn.\\u003c/p\\u003e\\u003ch2 style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e4. Không Kiếp tại cung Mệnh\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eKhi Địa Không và Địa Kiếp đóng tại hoặc hội chiếu cung Mệnh, cần xem xét toàn bộ bố cục lá số thay vì chỉ căn cứ vào hai sao này để kết luận tốt xấu.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eNgười có cách cục Không Kiếp thường được luận là có cuộc đời nhiều biến chuyển, tính cách khó đoán hoặc không thích đi theo con đường thông thường. Có người trải qua những giai đoạn thăng trầm rõ rệt, nhưng cũng có người nhờ tư duy khác biệt và sự quyết đoán mà tạo dựng được hướng đi riêng.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eĐiều quan trọng là phải xét thêm chính tinh thủ Mệnh, cung Thân, tam phương tứ chính, các sao hội hợp và vận hạn. Không Kiếp không đồng nghĩa với thất bại hay số phận bất hạnh; ý nghĩa cụ thể phụ thuộc vào toàn bộ lá số.\\u003c/p\\u003e\\u003ch2 style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e5. Không Kiếp trong công danh và tài lộc\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eTrong phương diện công danh, Không Kiếp thường được liên hệ với những bước ngoặt nghề nghiệp, sự thay đổi môi trường làm việc hoặc con đường phát triển không theo lối mòn. Người có bộ sao này cần chú trọng tính ổn định, kế hoạch dài hạn và khả năng kiểm soát rủi ro.\\u003c/p\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eVề tài lộc, Không Kiếp thường được xem là bộ sao cần thận trọng khi đầu tư, kinh doanh hoặc quyết định những khoản tiền lớn. Đặc biệt, không nên vì lợi ích trước mắt mà bỏ qua việc kiểm chứng thông tin và đánh giá khả năng thua lỗ. Khi có các sao tài lộc, quyền tinh và cát tinh hỗ trợ, vẫn cần xét sự phối hợp giữa các sao để luận đoán mức độ thuận lợi.\\u003c/p\\u003e\\u003ch2 style=\\\"font-size: 17px; font-family: Inter, system-ui, -apple-system, sans-serif; color: rgb(122, 20, 20); margin: 20px 0px 10px; line-height: 1.45; font-weight: 700;\\\"\\u003e6. Cách luận giải Không Kiếp chính xác\\u003c/h2\\u003e\\u003cp style=\\\"color: rgb(44, 36, 30); font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; font-weight: normal;\\\"\\u003eMuốn luận giải Địa Không và Địa Kiếp, cần chú ý các yếu tố sau:\\u003c/p\\u003e\\u003cul data-spread=\\\"false\\\"\\u003e\\u003cli style=\\\"line-height: 1.65; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-size: 14px; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; font-weight: normal;\\\"\\u003e\\u003cp style=\\\"font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-weight: normal;\\\"\\u003e\\u003cstrong\\u003eVị trí đóng sao:\\u003c/strong\\u003e Xét Không Kiếp tại cung Mệnh, Thân, Quan Lộc, Tài Bạch, Điền Trạch hay các cung khác.\\u003c/p\\u003e\\u003c/li\\u003e\\u003cli style=\\\"line-height: 1.65; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-size: 14px; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; font-weight: normal;\\\"\\u003e\\u003cp style=\\\"font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-weight: normal;\\\"\\u003e\\u003cstrong\\u003eChính tinh đồng cung:\\u003c/strong\\u003e Xem Không Kiếp kết hợp với Tử Vi, Thiên Phủ, Thiên Tướng, Thất Sát, Phá Quân và những chính tinh khác như thế nào.\\u003c/p\\u003e\\u003c/li\\u003e\\u003cli style=\\\"line-height: 1.65; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-size: 14px; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; font-weight: normal;\\\"\\u003e\\u003cp style=\\\"font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-weight: normal;\\\"\\u003e\\u003cstrong\\u003eCát tinh và hung tinh:\\u003c/strong\\u003e Đánh giá các sao hội hợp, sự hỗ trợ hoặc gia tăng tính chất bất lợi của bộ Không Kiếp.\\u003c/p\\u003e\\u003c/li\\u003e\\u003cli style=\\\"line-height: 1.65; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-size: 14px; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; font-weight: normal;\\\"\\u003e\\u003cp style=\\\"font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-weight: normal;\\\"\\u003e\\u003cstrong\\u003eĐại hạn và tiểu hạn:\\u003c/strong\\u003e Xem xét thời điểm các sao tác động, tránh lấy một cách cục cố định để kết luận toàn bộ cuộc đời.\\u003c/p\\u003e\\u003c/li\\u003e\\u003cli style=\\\"line-height: 1.65; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-size: 14px; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; font-weight: normal;\\\"\\u003e\\u003cp style=\\\"font-size: 14px; line-height: 1.65; text-align: justify; font-family: Inter, system-ui, -apple-system, sans-serif; margin: 0px 0px 12px; color: rgb(44, 36, 30); font-weight: normal;\\\"\\u003e\\u003cstrong\\u003eSự cân bằng của lá số:\\u003c/strong\\u003e Phải luận tổng thể cung Mệnh, cung Thân, tam phương tứ chính và các cung liên quan.\\u003c/p\\u003e\\u003c/li\\u003e\\u003c/ul\\u003e\",\"noiBat\":true,\"uuTienFeed\":1,\"updatedAt\":1795000000000},{\"id\":\"tuvi-ngay-12-con-giap\",\"tieuDe\":\"Tử Vi Hôm Nay: Luận Đoán Cát Hung 12 Con Giáp \\u0026 Giờ Hoàng Đạo Khởi Sự\",\"chuyenMuc\":\"Xem tử vi hàng ngày\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"15/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tử Vi Hàng Ngày.jpeg\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Dự báo chi tiết vận trình công danh, tài lộc, tình duyên của 12 con giáp trong ngày hôm nay. Hướng dẫn chọn khung giờ đại cát và hướng xuất hành nghênh tiếp Hỷ Thần, Tài Thần.\",\"noiDung\":\"\\n      \\u003cp style=\\\"font-size: 15.5px; line-height: 1.8; color: #2C241E; margin-bottom: 18px; text-align: justify;\\\"\\u003e\\n        \\u003cstrong\\u003eTử vi hàng ngày\\u003c/strong\\u003e là nội dung giúp bạn tham khảo những xu hướng và diễn biến nổi bật có thể xảy ra trong một ngày cụ thể dựa trên \\u003cstrong\\u003enăm sinh\\u003c/strong\\u003e, \\u003cstrong\\u003egiới tính\\u003c/strong\\u003e và \\u003cstrong\\u003engày Can Chi được lựa chọn\\u003c/strong\\u003e. Khác với việc xem tổng quan vận mệnh cả đời, tử vi hàng ngày tập trung vào trường khí của từng ngày, từ đó đưa ra những thông tin tham khảo về công việc, tài lộc, tình cảm, gia đạo, sức khỏe và các hoạt động nên thực hiện hoặc cần lưu ý. Khi xem tử vi hàng ngày, hệ thống sẽ kết hợp nhiều yếu tố như \\u003cstrong\\u003eCan Chi năm sinh\\u003c/strong\\u003e, \\u003cstrong\\u003engũ hành bản mệnh\\u003c/strong\\u003e, trường khí Can Chi của ngày để đưa ra lời khuyên phù hợp nhất.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e1. Tổng quan trường khí và cục diện cát hung ngày hôm nay\\u003c/h3\\u003e\\n      \\u003cp\\u003eTrong thuật số tử vi, vận trình mỗi ngày chịu ảnh hưởng sâu sắc bởi sự vận hành của Thiên Can, Địa Chi và hệ sao Lưu Nhật. Ngày hôm nay mang trường khí cân bằng, rất thích hợp cho việc mưu cầu công việc, ký kết giấy tờ hợp đồng hoặc bàn bạc kế hoạch kinh doanh lâu dài.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e2. Dự đoán vận thế từng nhóm tuổi tiêu biểu\\u003c/h3\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Nhóm tuổi Tý - Thìn - Thân (Tam Hợp Thủy Cục):\\u003c/strong\\u003e Có quý nhân tương trợ, công việc hành thông suôn sẻ. Tài lộc khởi sắc vào buổi chiều, thích hợp thu hồi nợ đọng hoặc giao dịch quan trọng.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Nhóm tuổi Dần - Ngọ - Tuất (Tam Hợp Hỏa Cục):\\u003c/strong\\u003e Tinh thần phấn chấn, có nhiều sáng kiến đột phá. Tuy nhiên cần chú ý lời ăn tiếng nói, tránh nóng nảy trong các cuộc họp mặt giao lưu.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Nhóm tuổi Tỵ - Dậu - Sửu (Tam Hợp Kim Cục):\\u003c/strong\\u003e Vận trình tài chính ổn định, có lộc ăn uống hoặc quà tặng từ đối tác. Gia đạo bình an hòa thuận.\\u003c/p\\u003e\\n      \\u003cp\\u003e\\u003cstrong\\u003e• Nhóm tuổi Hợi - Mão - Mùi (Tam Hợp Mộc Cục):\\u003c/strong\\u003e Khởi sắc về mặt tình duyên và quan hệ xã giao. Người độc thân có cơ hội gặp gỡ đối tượng tâm đầu ý hợp.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e3. Bảng giờ hoàng đạo đại cát trong ngày\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eGiờ Mão (05h - 07h):\\u003c/strong\\u003e Ngọc Đường Hoàng Đạo – Cát lợi cho việc dâng hương, khai trương mở hàng.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eGiờ Tỵ (09h - 11h):\\u003c/strong\\u003e Tư Mệnh Hoàng Đạo – Cực tốt cho việc ký kết hợp đồng, gặp gỡ đối tác quý nhân.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eGiờ Thân (15h - 17h):\\u003c/strong\\u003e Thanh Long Hoàng Đạo – Thuận lợi cầu tài lộc, xuất hành đi xa an toàn như ý.\\u003c/p\\u003e\\n    \"},{\"id\":\"tuvi-tuan-chuyen-bien-tai-loc\",\"tieuDe\":\"Tử Vi Tuần Mới: Chuyển Biến Cung Tài Bạch \\u0026 Sự Nghiệp 12 Tuổi\",\"chuyenMuc\":\"Xem tử vi hàng tuần\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"14/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tử Vi Theo Tuần.png\",\"noiBat\":false,\"uuTienFeed\":2,\"tomTat\":\"Khám phá diễn biến vận hạn trong 7 ngày tới. Nhận diện các cung hoàng đạo và tuổi gặp vận quý nhân dẫn lối, cũng như các lưu ý phong thủy để bảo toàn nguồn tài chính.\",\"noiDung\":\"\\u003ch3\\u003e1. Bức tranh vận trình tuần mới tổng quát\\u003c/h3\\u003e\\n      \\u003cp\\u003eBước sang tuần mới, vầng nhật nguyệt hội tụ nhiều cát tinh mang lại năng lượng chuyển mình tích cực. Những ai đang ấp ủ dự án mới nên nhanh chóng triển khai vào đầu tuần (từ Thứ Hai đến Thứ Tư) để nắm trọn thiên thời địa lợi.\\u003c/p\\u003e\\n\\n      \\n\\n      \\u003ch3\\u003e2. Điểm sáng tài lộc và sự nghiệp\\u003c/h3\\u003e\\n      \\u003cp\\u003eNhững bản mệnh mang hành Thổ và Kim sẽ đón nhận nhiều vận may bất ngờ về tiền bạc trong tuần này. Khoản thu phụ từ công việc tự do hoặc đầu tư tay trái có xu hướng gia tăng đáng kể.\\u003c/p\\u003e\\n      \\u003cp\\u003eĐối với chốn công sở, sự hòa nhã và thấu hiểu đồng nghiệp sẽ giúp bạn giải tỏa được các khúc mắc tồn đọng từ tuần trước, tạo tiền đề vững chắc cho việc thăng quan tiến chức.\\u003c/p\\u003e\"},{\"id\":\"tuvi-thang-nguyet-lenh\",\"tieuDe\":\"Tử Vi Tháng Này: Dự Đoán Vượng Suy Tài Vận Theo Lịch Nguyệt Lệnh\",\"chuyenMuc\":\"Xem tử vi hàng tháng\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"10/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Tử Vi Theo Tháng.jpeg\",\"noiBat\":false,\"uuTienFeed\":3,\"tomTat\":\"Cẩm nang dự báo xu thế tháng theo chu kỳ tiết khí và tiết lệnh. Hướng dẫn các phương thức kích hoạt tài lộc, bình ổn gia đạo và phòng ngừa hao tán tiền của.\",\"noiDung\":\"\\n      \\u003cp style=\\\"font-size: 15.5px; line-height: 1.8; color: #2C241E; margin-bottom: 18px; text-align: justify;\\\"\\u003e\\n        \\u003cstrong\\u003eTử vi theo tháng\\u003c/strong\\u003e giúp bạn nắm bắt được những xu hướng nổi bật trong từng tháng của năm, từ đó có sự chuẩn bị tốt hơn trong công việc, tài chính, tình cảm và sức khỏe để mỗi tháng đều là một khởi đầu tốt đẹp.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e1. Quy luật nguyệt lệnh chi phối vận hạn tháng\\u003c/h3\\u003e\\n      \\u003cp\\u003eMỗi tháng âm lịch đại diện cho một mùa khí và vị trí tinh tú riêng biệt. Khi sao Lưu Nguyệt di chuyển qua các cung vị trên lá số tử vi cá nhân, nó sẽ kích hoạt các sự kiện trọng đại về sức khỏe, điền sản, gia quyến.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e2. Các lưu ý trọng yếu trong tháng\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eVề phương diện sức khỏe:\\u003c/strong\\u003e Tiết trời giao hòa dễ gây ra bệnh đường hô hấp hoặc đau mỏi gân cốt. Cần chú trọng chế độ ẩm thực thanh đạm và nghỉ ngơi điều độ.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eVề đầu tư kinh doanh:\\u003c/strong\\u003e Tránh các thương vụ mang tính chất rủi ro cao hoặc đầu cơ lướt sóng. Hãy tập trung củng cố nền tảng tài chính hiện có.\\u003c/p\\u003e\\n    \"},{\"id\":\"tuvi-tron-doi-giai-ma-menh-than\",\"tieuDe\":\"Tử Vi Trọn Đời: Giải Mã Bản Đồ Định Mệnh Qua Cung Mệnh \\u0026 Cung Thân\",\"chuyenMuc\":\"Xem tử vi trọn đời\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"08/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Tử Vi Cung Mệnh Cung Thân.png\",\"noiBat\":true,\"uuTienFeed\":4,\"tomTat\":\"Khám phá cấu trúc cốt lõi của lá số tử vi trọn đời. Phân tích mối tương quan giữa cung Mệnh (tiền định) và cung Thân (hậu thiên lập nghiệp) quyết định họa phúc một kiếp người.\",\"noiDung\":\"\\u003ch3\\u003e1. Cung Mệnh và Cung Thân: Gốc rễ của số phận\\u003c/h3\\u003e\\n      \\u003cp\\u003eTrong nghệ thuật dự trắc Tử Vi Đẩu Số, \\u003cstrong\\u003eCung Mệnh\\u003c/strong\\u003e được coi là gốc rễ, thể hiện hình hài, cốt cách, tính cách thiên bẩm và vận mệnh nửa đầu cuộc đời (từ nhỏ đến khoảng 30 - 32 tuổi). Trong khi đó, \\u003cstrong\\u003eCung Thân\\u003c/strong\\u003e là nơi nương tựa của hậu thiên, phản ánh hành động, nỗ lực cá nhân và giai đoạn từ tuổi trung niên trở về già.\\u003c/p\\u003e\\n\\n      \\n\\n      \\u003ch3\\u003e2. Mối quan hệ giữa Cung Mệnh và Ngũ Hành Bản Mệnh\\u003c/h3\\u003e\\n      \\u003cp\\u003eMột lá số thượng cách khi Ngũ Hành của bản mệnh tương sinh hoặc tỷ hòa với Ngũ Hành của vị trí cung an Mệnh. Ví dụ: Người mệnh Hỏa cư tại cung Dần, Mão (Mộc) gọi là Mộc sinh Hỏa, suốt đời dễ gặp hoàn cảnh tương trợ, gặp nguy hóa an.\\u003c/p\\u003e\\n      \\n      \\u003ch3\\u003e3. Lời khuyên tu tâm dưỡng tính cải mệnh\\u003c/h3\\u003e\\n      \\u003cblockquote\\u003e\\\"Đức năng thắng số - Nhân định thắng thiên. Lá số tử vi chỉ ra khuynh hướng của vũ trụ, nhưng cách lựa chọn, sự tích đức hành thiện và nghị lực bản thân mới là yếu tố quyết định nấc thang thành tựu cuối cùng.\\\"\\u003c/blockquote\\u003e\"},{\"id\":\"tuvi-van-han-dai-van-tieu-han\",\"tieuDe\":\"Xem Vận Hạn Tử Vi: Cách Tính Đại Vận 10 Năm \\u0026 Hóa Giải Sát Tinh Cung Hạn\",\"chuyenMuc\":\"Xem vận hạn tử vi\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"05/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xem Vận Hạn Tử Vi.png\",\"noiBat\":false,\"uuTienFeed\":5,\"tomTat\":\"Hướng dẫn nhận diện chu kỳ Đại Hạn 10 năm và Tiểu Hạn hàng năm. Phương pháp ứng phó và hóa giải khi gặp các sao sát tinh như Hóa Kỵ, Kình Dương, Đà La, Không Kiếp.\",\"noiDung\":\"\\u003ch3\\u003e1. Cơ chế vận hành của Đại Vận và Lưu Niên Tiểu Hạn\\u003c/h3\\u003e\\n      \\u003cp\\u003eMột đời người trải qua nhiều chu kỳ Đại Vận 10 năm. Tùy theo Cục số (Thủy Nhị Cục, Mộc Tam Cục, Kim Tứ Cục, Thổ Ngũ Cục, Hỏa Lục Cục) mà tuổi bắt đầu bước vào Đại Vận sẽ rơi vào 2, 3, 4, 5 hoặc 6 tuổi.\\u003c/p\\u003e\\n\\n      \\n\\n      \\u003ch3\\u003e2. Nhận diện các sao hung sát tinh thường gặp\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eKình Dương - Đà La:\\u003c/strong\\u003e Đại diện cho chông gai, trở ngại, thị phi kiện tụng hoặc phẫu thuật thương tật.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eHỏa Tinh - Linh Tinh:\\u003c/strong\\u003e Kích phát tính nóng nảy, bất ngờ gặp biến cố hoặc hao tốn công sức.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eĐịa Không - Địa Kiếp:\\u003c/strong\\u003e Tượng trưng cho sự mất mát tài chính bất ngờ, mưu sự khó thành nếu tâm cơ quá cao.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eHóa Kỵ:\\u003c/strong\\u003e Sao của sự nghi kỵ, ghen ghét và cản trở tiến trình công danh.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e3. Bí quyết chuyển hóa hung hiểm\\u003c/h3\\u003e\\n      \\u003cp\\u003eKhi bước vào cung hạn gặp sát tinh, cổ nhân khuyên nên \\\"Tĩnh dĩ đãi động\\\" (giữ tâm thái tĩnh lặng, cẩn trọng trong từng bước đi). Tăng cường bố thí, hành thiện, giữ gìn chữ tín và cẩn trọng giấy tờ là liều thuốc hữu hiệu nhất để biến hung thành cát.\\u003c/p\\u003e\"},{\"id\":\"tuvi-can-xuong-tinh-cot\",\"tieuDe\":\"Cân Xương Đoán Số: Bảng Tra Cân Xương Tính Cốt \\u0026 Giải Mã Lượng Chỉ Cuộc Đời\",\"chuyenMuc\":\"Cân xương đoán số\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"02/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Cân Xương Đoán Số.png\",\"noiBat\":false,\"uuTienFeed\":6,\"tomTat\":\"Phương pháp Cân Xương Tính Cốt trứ danh của Lão Tử và Viên Thiên Cang. Hướng dẫn tính tổng lượng chỉ Năm - Tháng - Ngày - Giờ sinh và tra cứu bài thơ định mệnh chuẩn xác.\",\"noiDung\":\"\\n      \\u003cp style=\\\"font-size: 15.5px; line-height: 1.8; color: #2C241E; margin-bottom: 18px; text-align: justify;\\\"\\u003e\\n        \\u003cstrong\\u003eCân xương đoán số\\u003c/strong\\u003e (còn gọi là \\u003cstrong\\u003eCân Xương Tính Cốt\\u003c/strong\\u003e hay \\u003cstrong\\u003eLượng Chỉ Đoán Mệnh\\u003c/strong\\u003e) là phương pháp chiêm tinh bí truyền trứ danh của bậc tiền nhân \\u003cstrong\\u003eViên Thiên Cang\\u003c/strong\\u003e đời nhà Đường. Bằng cách quy đổi \\u003cstrong\\u003eNăm sinh\\u003c/strong\\u003e, \\u003cstrong\\u003eTháng sinh\\u003c/strong\\u003e, \\u003cstrong\\u003eNgày sinh\\u003c/strong\\u003e và \\u003cstrong\\u003eGiờ sinh Âm Lịch\\u003c/strong\\u003e thành đơn vị \\u003cem\\u003eLượng\\u003c/em\\u003e và \\u003cem\\u003eChỉ\\u003c/em\\u003e, hệ thống cộng tổng trọng lượng số mệnh để luận giải công danh, tiền tài, gia đạo, thăng trầm và hậu vận một kiếp người.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e1. Giới thiệu nguồn gốc thuật Cân Xương Tính Cốt\\u003c/h3\\u003e\\n      \\u003cp\\u003ePhương pháp \\u003cstrong\\u003eCân Xương Đoán Số\\u003c/strong\\u003e là một tuyệt kỹ chiêm tinh cổ truyền được tương truyền do bậc cao nhân Viên Thiên Cang biên soạn. Phương pháp này quy đổi Năm sinh, Tháng sinh, Ngày sinh và Giờ sinh âm lịch thành đơn vị \\u0027Lượng\\u0027 và \\u0027Chỉ\\u0027 để đúc kết số mệnh qua những bài phú thơ cổ truyền xác thực.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e2. Cách tính tổng số lượng chỉ bản mệnh\\u003c/h3\\u003e\\n      \\u003cp\\u003eCông thức cơ bản:\\u003c/p\\u003e\\n      \\u003cdiv style=\\\"background: #FFFDF8; border: 1.5px solid #DFBA73; padding: 14px 18px; border-radius: 6px; font-weight: 700; color: #7A1414; margin: 12px 0;\\\"\\u003e\\n        TỔNG SỐ LƯỢNG CHỈ = Lượng Năm + Lượng Tháng + Lượng Ngày + Lượng Giờ\\n      \\u003c/div\\u003e\\n      \\u003cp\\u003eTổng số lượng chỉ nhẹ nhất là \\u003cstrong\\u003e2 lượng 1 chỉ\\u003c/strong\\u003e, và nặng nhất đạt đến \\u003cstrong\\u003e7 lượng 1 chỉ\\u003c/strong\\u003e. Thông thường, số chỉ càng cao thì vận số tiền tài, phước lộc càng hanh thông sung túc.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e3. Ý nghĩa khái lược các thang lượng chỉ\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTừ 2 lượng 2 đến 3 lượng 5:\\u003c/strong\\u003e Tuổi trẻ gian nan vất vả, phải tự lực cánh sinh, lập nghiệp tha hương mới mong thành công. Về hậu vận sẽ dần ổn định ấm no.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTừ 3 lượng 6 đến 4 lượng 8:\\u003c/strong\\u003e Số phận thanh nhã, có tài nghệ và chữ tín. Công danh sự nghiệp phát triển vững vàng từ độ trung niên, gia đạo hòa thuận.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTừ 4 lượng 9 đến 6 lượng 0:\\u003c/strong\\u003e Số hưởng vinh hoa phú quý, sinh ra trong gia đình gia giáo hoặc có quý nhân kề cận nâng đỡ, tiền bạc dồi dào, thọ khang trường cửu.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTừ 6 lượng 1 đến 7 lượng 1:\\u003c/strong\\u003e Mệnh cách quý hiển tột bậc, đại phú đại quý, làm rạng danh dòng tộc và được muôn người kính trọng.\\u003c/p\\u003e\\n    \"},{\"id\":\"tuvi-12-con-giap-dau-nam\",\"tieuDe\":\"Xem Tử Vi Năm 2026: Luận Đoán Cát Hung 12 Con Giáp \\u0026 Vận Trình Đầu Xuân\",\"chuyenMuc\":\"Tử Vi 2026\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"26/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Tử Vi 2026.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Dự báo chi tiết vận trình công danh, tài lộc, gia đạo và sức khỏe của 12 con giáp trong năm mới. Khám phá các cơ hội phát triển và phương vị nghênh tiếp cát thần đại cát.\",\"noiDung\":\"\\n      \\u003cp style=\\\"font-size: 15.5px; line-height: 1.8; color: #2C241E; margin-bottom: 18px; text-align: justify;\\\"\\u003e\\n        \\u003cstrong\\u003eTử vi đầu năm 2026\\u003c/strong\\u003e là nội dung giúp bạn tham khảo những xu hướng và diễn biến nổi bật có thể xảy ra trong năm mới dựa trên \\u003cstrong\\u003enăm sinh\\u003c/strong\\u003e, \\u003cstrong\\u003egiới tính\\u003c/strong\\u003e và \\u003cstrong\\u003engũ hành bản mệnh\\u003c/strong\\u003e. Khác với việc xem tử vi hàng ngày hay tử vi trọn đời, tử vi đầu năm tập trung sâu vào trường khí của năm mới \\u003cstrong\\u003eBính Ngọ 2026\\u003c/strong\\u003e, từ đó đưa ra những thông tin tham khảo toàn diện về công việc, tài lộc, tình cảm, gia đạo, sức khỏe và các hoạt động nên thực hiện hoặc cần lưu ý. Khi xem tử vi đầu năm, hệ thống sẽ kết hợp nhiều yếu tố như \\u003cstrong\\u003eCan Chi năm sinh\\u003c/strong\\u003e, \\u003cstrong\\u003engũ hành bản mệnh\\u003c/strong\\u003e, \\u003cstrong\\u003esao chiếu mệnh Lưu Niên\\u003c/strong\\u003e, \\u003cstrong\\u003ehạn Tam Tai - Kim Lâu - Hoang Ốc\\u003c/strong\\u003e và \\u003cstrong\\u003evận hạn Thái Tuế\\u003c/strong\\u003e để luận giải chi tiết và đưa ra lời khuyên đón lành tránh dữ cho từng bản mệnh.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e1. Bức tranh vận trình 12 Con Giáp đầu xuân năm mới\\u003c/h3\\u003e\\n      \\u003cp\\u003eMỗi chu kỳ năm mới mở ra sự chuyển dịch của các chòm sao Lưu Niên như Thái Tuế, Tuế Phá, Lộc Tồn, Thiên Mã, Tang Môn, Bạch Hổ. Việc nắm bắt hung cát vận hạn ngay từ đầu xuân giúp quý bản mệnh chủ động nghênh đón cát khí, hạn chế rủi ro và phát huy tối đa tiềm năng bản thân.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e2. Đặc Điểm Tính Cách 12 Con Giáp\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Tý:\\u003c/strong\\u003e Nhanh nhẹn, thông minh và sắc sảo trong phán đoán. Họ luôn biết nắm bắt thời cơ để gặt hái thành công trong cuộc sống.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Sửu:\\u003c/strong\\u003e Siêng năng, kiên định và chịu thương chịu khó. Họ sở hữu ý chí vững vàng và tinh thần trách nhiệm cực kỳ cao.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Dần:\\u003c/strong\\u003e Mạnh mẽ, quả cảm và tràn đầy nhiệt huyết. Họ mang phong thái của người lãnh đạo, sẵn sàng đương đầu với mọi thử thách.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Mão:\\u003c/strong\\u003e Tinh tế, khôn ngoan và sống rất ôn hòa, khéo léo. Họ luôn cẩn trọng trong mọi việc và tạo được thiện cảm lớn với xung quanh.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Thìn:\\u003c/strong\\u003e Uy quyền, hào phóng và có tầm nhìn chiến lược lớn. Họ luôn tỏa ra nguồn năng lượng mạnh mẽ để chinh phục những đỉnh cao mới.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Tỵ:\\u003c/strong\\u003e Sáng suốt, điềm tĩnh và ẩn chứa trí tuệ uyên bác. Họ có trực giác nhạy bén và luôn giữ được thế chủ động trong mọi tình huống.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Ngọ:\\u003c/strong\\u003e Phóng khoáng, nhiệt tình và luôn yêu thích sự tự do. Họ sở hữu nguồn năng lượng dồi dào và sự xông xáo trong mọi hành trình.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Mùi:\\u003c/strong\\u003e Nhân hậu, hiền hòa và sống giàu tình cảm. Họ mang tâm hồn nghệ sĩ, sự nhẫn nại và là điểm tựa bình yên cho mọi người.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Thân:\\u003c/strong\\u003e Thông minh tột đỉnh, linh hoạt và ứng biến cực kỳ giỏi. Họ hài hước, dí dỏm và có tài ngoại giao xuất sắc.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Dậu:\\u003c/strong\\u003e Chăm chỉ, sắc sảo và có kỷ luật bản thân rất cao. Họ luôn chỉn chu trong mọi chi tiết và rất ngay thẳng, trượng nghĩa.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Tuất:\\u003c/strong\\u003e Trung thành, trượng nghĩa và đặt chữ tín lên hàng đầu. Họ sống chân thành và luôn sẵn sàng bảo vệ những người xung quanh.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eTuổi Hợi:\\u003c/strong\\u003e Phúc hậu, bao dung và luôn biết tận hưởng cuộc sống an nhiên. Họ thường gặp nhiều may mắn, quý nhân phù trợ và sự viên mãn.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e3. Phân tích chi tiết 4 nhóm Tam Hợp \\u0026 Vận hội mới\\u003c/h3\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eNhóm Thân - Tý - Thìn (Tam Hợp Thủy Cục):\\u003c/strong\\u003e Có nhiều cơ hội mở rộng quan hệ hợp tác làm ăn, tài chính có bước chuyển biến tích cực, nên chủ động nắm bắt thời cơ từ quý 2 trở đi.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eNhóm Dần - Ngọ - Tuất (Tam Hợp Hỏa Cục):\\u003c/strong\\u003e Năng lượng dồi dào, sự nghiệp thăng hoa nhưng cần giữ tâm thế khiêm tốn, tránh bốc đồng trong các quyết định đầu tư mạo hiểm.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eNhóm Tỵ - Dậu - Sửu (Tam Hợp Kim Cục):\\u003c/strong\\u003e Tài lộc tích lũy vững vàng, công việc kinh doanh đi vào quỹ đạo ổn định, gia đạo đón nhận nhiều tin vui hỷ sự.\\u003c/p\\u003e\\n      \\u003cp\\u003e• \\u003cstrong\\u003eNhóm Hợi - Mão - Mùi (Tam Hợp Mộc Cục):\\u003c/strong\\u003e Khởi sắc về đường nhân duyên và học hành, thi cử, quý nhân tương trợ giúp vượt qua thử thách một cách êm đẹp.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e4. Phương vị và giờ lành xuất hành nghênh Tài Thần, Hỷ Thần\\u003c/h3\\u003e\\n      \\u003cp\\u003eVào ngày đầu năm mới, việc lựa chọn hướng xuất hành thuận phong thủy đóng vai trò khai mở luồng sinh khí may mắn. Quý gia chủ nên tra cứu kỹ hướng đón Tài Thần và Hỷ Thần hợp với bản mệnh để cả năm vạn sự cát tường.\\u003c/p\\u003e\\n    \"},{\"id\":\"xong-dat-dau-nam-dai-cat\",\"tieuDe\":\"Xông Đất Đầu Năm 2026: Cẩm Nang Chọn Tuổi Xông Nhà, Mở Hàng Đại Cát\",\"chuyenMuc\":\"Xông Đất Đầu Năm 2026\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"26/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Xông Đất Đầu Năm 2026.png\",\"noiBat\":true,\"uuTienFeed\":2,\"tomTat\":\"Nghệ thuật chọn tuổi xông đất, mở hàng đầu năm mới chuẩn phong thủy cát nhật. Bảng 5 tiêu chí vàng Tam Hợp, Lục Hợp, Ngũ Hành tương sinh và quy trình 3 bước tự xông đất cho gia chủ.\",\"noiDung\":\"\\n      \\u003cp style=\\\"font-size: 15.5px; line-height: 1.8; color: #2C241E; margin-bottom: 18px; text-align: justify;\\\"\\u003e\\n        \\u003cstrong\\u003eXông đất đầu năm 2026\\u003c/strong\\u003e (còn gọi là \\u003cem\\u003eđạp đất\\u003c/em\\u003e) là một nét đẹp văn hóa lâu đời của dân tộc Việt Nam vào thời khắc chuyển giao năm mới. Người xưa tin rằng người đầu tiên bước chân vào nhà sau giờ Giao thừa sẽ đem lại vận khí, may rủi và phúc lộc cho gia chủ trong suốt 365 ngày của năm đó. Dựa trên \\u003cstrong\\u003enăm sinh của gia chủ\\u003c/strong\\u003e và \\u003cstrong\\u003enăm xem\\u003c/strong\\u003e, hệ thống sẽ đối chiếu toàn diện về \\u003cstrong\\u003eThiên Can\\u003c/strong\\u003e, \\u003cstrong\\u003eĐịa Chi (Tam Hợp, Lục Hợp)\\u003c/strong\\u003e, \\u003cstrong\\u003eNgũ Hành tương sinh\\u003c/strong\\u003e và \\u003cstrong\\u003eVận Niên\\u003c/strong\\u003e để chọn ra những tuổi xông nhà, xông đất và mở hàng đại cát nhất, giúp kích hoạt tài lộc, bình an cho cả gia đình.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3 style=\\\"font-family: \\u0027Cinzel\\u0027, serif; color: var(--primary, #7A1414); font-size: 17px; font-weight: 800; margin-top: 22px; margin-bottom: 12px; border-left: 4px solid var(--gold, #DFBA73); padding-left: 10px;\\\"\\u003e\\n        1. Ý nghĩa \\u0026amp; Bí quyết chọn người Xông Đất đầu xuân\\n      \\u003c/h3\\u003e\\n      \\u003cp style=\\\"margin-bottom: 16px; text-align: justify;\\\"\\u003e\\n        Thời khắc sau Giao thừa là lúc đất trời giao hòa, âm dương chuyển dịch và trường khí trong ngôi nhà bắt đầu khởi tạo cho một chu kỳ vận hành mới. Người bước chân đầu tiên vào nhà sau giờ Giao thừa mang theo nguồn sinh khí quyết định đến sự hanh thông của gia đạo. Một người xông đất hợp tuổi, bản mệnh tương sinh, tính tình vui vẻ, hiền hòa và đang làm ăn phát đạt sẽ đem lại vượng khí dồi dào, xua tan điều xui rủi và mang tới cả năm an khang thịnh vượng.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3 style=\\\"font-family: \\u0027Cinzel\\u0027, serif; color: var(--primary, #7A1414); font-size: 17px; font-weight: 800; margin-top: 22px; margin-bottom: 12px; border-left: 4px solid var(--gold, #DFBA73); padding-left: 10px;\\\"\\u003e\\n        2. 5 Tiêu chí vàng chọn người Xông Đất, Mở Hàng đại cát\\n      \\u003c/h3\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eTương sinh về Ngũ Hành, Tam Hợp, Lục Hợp:\\u003c/strong\\u003e Bản mệnh và Thiên can, Địa chi của người xông đất tương sinh hỗ trợ cho gia chủ (Mộc sinh Hỏa, Hỏa sinh Thổ, Thổ sinh Kim, Kim sinh Thủy, Thủy sinh Mộc; thuộc các bộ Tam Hợp, Lục Hợp cát tường) và không bị xung khắc với Thái Tuế của năm.\\n      \\u003c/p\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eTránh Tứ Hành Xung \\u0026amp; Tương Hại:\\u003c/strong\\u003e Tuyệt đối không chọn người có tuổi chính xung (Tý - Ngọ, Mão - Dậu, Dần - Thân, Tỵ - Hợi, Thìn - Tuất, Sửu - Mùi) hoặc tương hại, tương phá với bản mệnh chủ nhà.\\n      \\u003c/p\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eVía Lành, Tính Tình Xởi Lởi:\\u003c/strong\\u003e Chọn người hoạt bát, vui vẻ, hiền hòa, sống có đức và luôn mang lại năng lượng tích cực cho mọi người xung quanh.\\n      \\u003c/p\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eCông Việc Làm Ăn Thuận Lợi:\\u003c/strong\\u003e Ưu tiên người đang trên đà phát đạt, tài chính hanh thông, công danh thăng tiến để \\\"nhả vía lộc\\\" cho nhà mình.\\n      \\u003c/p\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eGia Đình Thuận Hòa, Ấm Êm:\\u003c/strong\\u003e Vợ chồng con cái hòa thuận, hiếu thảo, gia đạo yên vui, không có mâu thuẫn lục đục.\\n      \\u003c/p\\u003e\\n      \\u003cp style=\\\"margin-bottom: 10px;\\\"\\u003e\\n        • \\u003cstrong\\u003eKhông Mang Bụi Tang \\u0026amp; Vướng Biến Cố:\\u003c/strong\\u003e Kiêng kỵ tuyệt đối người đang chịu tang sự, phụ nữ đang mang thai hoặc gia đình gặp biến cố trắc trở trong năm vừa qua.\\n      \\u003c/p\\u003e\\n\\n      \\u003ch3 style=\\\"font-family: \\u0027Cinzel\\u0027, serif; color: var(--primary, #7A1414); font-size: 17px; font-weight: 800; margin-top: 22px; margin-bottom: 12px; border-left: 4px solid var(--gold, #DFBA73); padding-left: 10px;\\\"\\u003e\\n        3. Cách Gia Chủ Tự Xông Đất Cho Mình Chuẩn Phong Thủy\\n      \\u003c/h3\\u003e\\n      \\u003cp style=\\\"margin-bottom: 12px; text-align: justify;\\\"\\u003e\\n        Nếu trong trường hợp gia chủ không tìm được người có tuổi và tính cách ưng ý để nhờ xông đất, gia chủ hoàn toàn có thể \\u003cstrong\\u003etự xông đất cho chính ngôi nhà của mình\\u003c/strong\\u003e:\\n      \\u003c/p\\u003e\\n      \\u003cdiv style=\\\"background: #FAF6EF; border: 1px solid #E5D5BA; border-radius: 8px; padding: 14px 18px; margin-bottom: 16px;\\\"\\u003e\\n        \\u003cp style=\\\"margin: 0 0 10px 0; line-height: 1.6;\\\"\\u003e\\n          \\u003cstrong\\u003e• Bước 1:\\u003c/strong\\u003e Trước giờ Giao thừa (khoảng 23h00 đêm 30 Tết), một thành viên hợp tuổi trong gia đình mặc trang phục chỉnh tề, bước ra khỏi nhà.\\n        \\u003c/p\\u003e\\n        \\u003cp style=\\\"margin: 0 0 10px 0; line-height: 1.6;\\\"\\u003e\\n          \\u003cstrong\\u003e• Bước 2:\\u003c/strong\\u003e Đi đến đình, đền, chùa gần nhà hoặc đi về hướng Hỷ Thần / Tài Thần của năm để cầu an, hái lộc đầu xuân.\\n        \\u003c/p\\u003e\\n        \\u003cp style=\\\"margin: 0; line-height: 1.6;\\\"\\u003e\\n          \\u003cstrong\\u003e• Bước 3:\\u003c/strong\\u003e Đúng thời khắc sau Giao thừa (từ 00h15 đến 01h00 mùng 1), người đó quay trở về nhà, mang theo cành lộc may mắn hoặc bao lì xì đỏ vào nhà, gửi những lời chúc tốt lành đến các thành viên trong gia đình.\\n        \\u003c/p\\u003e\\n      \\u003c/div\\u003e\\n    \"},{\"id\":\"bai-pha-quan-dan-than\",\"tieuDe\":\"Phá Quân độc tọa ở hai cung Dần hoặc Thân\",\"chuyenMuc\":\"Tử Vi Đẩu Số\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"14/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Sao Phá Quan Dần Thân.png\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Phá Quân độc tọa hai cung Dần hoặc Thân; đối cung là \\u0027Vũ Khúc, Thiên Tướng\\u0027; cung tam phương là Thất Sát độc tọa. Cung Dần hoặc Thân là thế hãm địa của Phá Quân nhưng lại ẩn chứa tiềm năng khai mở vô cùng mãnh liệt, phá tan trở ngại để kiến thiết đại nghiệp vinh quang...\",\"noiDung\":\"\\u003cp\\u003ePhá Quân độc tọa hai cung Dần hoặc Thân; đối cung là \\\"Vũ Khúc, Thiên Tướng\\\"; cung tam phương là Thất Sát độc tọa. Cung Dần hoặc Thân là thế hãm địa của Phá Quân, chủ về sự khai sáng anh dũng phi thường, kiến lập sự nghiệp lớn trong bão táp.\\u003c/p\\u003e\\n      \\n      \\n      \\u003ch3\\u003e1. Đặc tính bản mệnh khi Phá Quân cư Dần Thân\\u003c/h3\\u003e\\n      \\u003cp\\u003ePhá Quân thuộc Thủy, hóa khí là Hao, chủ về sự xung phong trận mạc, không ngại gian khó, dám nghĩ dám làm và phá vỡ các khuôn mẫu cũ kỹ. Người có Phá Quân thủ Mệnh tại Dần Thân thường có tính cách độc lập từ rất sớm, sớm rời xa quê hương bản quán để tự thân lập nghiệp.\\u003c/p\\u003e\\n      \\u003cp\\u003eCuộc đời người này phải trải qua ít nhất một lần thăng trầm biến cố lớn trước khi đạt được đỉnh cao của danh vọng và tiền tài. Họ có tố chất của nhà cải cách, nhà kinh doanh tiên phong hoặc người đứng đầu các dự án đột phá.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e2. Ảnh hưởng của các sao hội tụ\\u003c/h3\\u003e\\n      \\u003cp\\u003eĐối cung có Vũ Khúc và Thiên Tướng chiếu về, mang lại năng lực tài chính và óc tổ chức quản trị thực tế. Nếu hội hợp được các cát tinh như Tả Phù, Hữu Bật, Hóa Lộc, Hóa Quyền thì đương số biến hung thành cát, danh tiếng vang dội bốn phương.\\u003c/p\\u003e\\n      \\u003cp\\u003eTuy nhiên, nếu gặp phải Kình Dương, Đà La, Không Kiếp hãm địa thì cần đề phòng tổn thất tài sản, nên chọn các ngành nghề kỹ thuật cao, cơ khí chế tạo, phẫu thuật ngoại khoa hoặc quân đội để hóa giải sát khí.\\u003c/p\\u003e\\n\\n      \\u003ch3\\u003e3. Lời khuyên định hướng sự nghiệp\\u003c/h3\\u003e\\n      \\u003cp\\u003eNgười mệnh Phá Quân Dần Thân không nên chọn những công việc văn phòng gò bó, an phận thủ thường. Môi trường càng nhiều thách thức, cạnh tranh khốc liệt thì tài năng của họ càng được phát huy rực rỡ. Hôn nhân nên kết hôn muộn để giữ gìn hòa khí gia đạo lâu bền.\\u003c/p\\u003e\"},{\"id\":\"post-ly-tinh-cua-sao-tu-vi-1639\",\"tieuDe\":\"LÝ TÍNH CỦA SAO TỬ VI\",\"chuyenMuc\":\"Tử Vi Đẩu Số\",\"tacGia\":\"Thầy Duy Tâm Phúc\",\"ngayDang\":\"15/09/2026\",\"hinhAnh\":\"Ảnh Bài Viết Khung 16-9/Lý Tính Của Sao Tử Vi.jpeg\",\"noiBat\":true,\"uuTienFeed\":1,\"tomTat\":\"Các chính tinh thuộc chòm Tử Vi sinh ra từ quẻ Càn, theo vị trí các hào từ cao xuống thấp mỗi hào một sao. Quẻ Càn ngoài 6 hào dương còn có một hào rất đặc biệt...\",\"noiDung\":\"\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eCác chính tinh thuộc chòm Tử Vi sinh ra từ quẻ Càn, theo vị trí các hào từ cao xuống thấp mỗi hào một sao. Quẻ Càn ngoài 6 hào dương còn có một \\u0027hào\\u0027 rất đặc biệt, đó là hào 7, \\u0027Dụng cửu, Kiến quần long vô thủ\\u0027, đây chính là chỗ phát sinh ra sao Thiên Phủ. Quẻ Càn toàn hào dương, nhưng lại dùng hào 7 chính là do gặp phải cái âm động. Trong Dịch có một môn là Thái Ất, khi xem quẻ Ất, để tìm hào động ứng việc ta phải xem địa chi động số rồi đếm các hào trong quẻ. Chi dương thì đếm hào dương, chi âm thì đếm hào âm. Quẻ Càn thuần dương, nếu gặp địa chi âm thì do không có hào âm nào nên kết quả toàn bộ các hào dương đều tĩnh, khi đó, ta dùng \\u0027hào 7\\u0027 để xét việc.\\u003c/p\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eSao Tử Vi còn gọi là Đế tọa đứng đầu 12 vì sao trong lá số Tử Vi, thuộc tính ngũ hành là Âm Thổ, là trung tâm của các vì sao. Tử Vi chuyên quản về tước lộc, có tác dụng hóa giải tai ách, kéo dài tuổi thọ, chủ hóa (chủ phúc và hóa giải hung tính của các sát tinh).\\u003c/p\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eTử Vi thuộc Âm Thổ chủ tinh Bắc đẩu, hóa là Đế Quân, thường là chủ tinh ắt sẽ cần \\u0027Quần Thần Củng Chiếu\\u0027. Chính vì thế mà Tử Vi nhất định phải được Quần Thần củng chiếu mới là thượng cách, nếu không có quần thần khánh hội thì chỉ là cách cục bình thường. Quần thần ở đây nếu như hội hợp được chủ tinh thì có sự trợ giúp rất lớn như Thiên Phủ - Thiên Tướng ắt sẽ mạnh mẽ, có tài, có thế. Là tượng của Đế Hoàng nên cần sự trợ sức của Tả Phù - Hữu Bật đồng cung phò tá, lòng dạ cũng rộng rãi. Nếu có Xương Khúc làm tùy tùng cùng hội hợp, thì có học thức, có trí tài, cũng có khả năng làm giảm nhẹ cái tính cao ngạo, chủ quan của Tử Vi. Khôi Việt chủ truyền lệnh hội hợp thì có nhân gặp nhiều cơ hội, có khả năng gia tăng địa vị. Thái Dương, Thái Âm phân chức. Gặp Lộc Tồn có nghĩa tiền bạc chất đống trong kho đụn.\\u003c/p\\u003e\\n\\u003cp style=\\\"font-size: 14pt; line-height: 1.5; font-weight: normal; text-align: justify; font-family: \\u0027Times New Roman\\u0027, Times, serif; margin: 0 0 12px 0; color: #222;\\\"\\u003eNếu như Quần Thần xa lánh, trở thành Cô Quân chủ quan quá sâu, tâm cao khí ngạo mà mừng giận thất thường, không khéo đối xử với người. Nếu gặp Không Vong - Hoa Cái thường có tư tưởng độc tài. Nếu gia Tứ Sát là vua vô đạo thuộc hạ cách, nếu thêm Phúc cung không tốt thì là người hèn mọn dung tục.\\u003c/p\\u003e\"}]"
};